INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(9281, 'plPL', 'Torowanie drogi', 'Magister Kaendris przysłał mnie tutaj, żebym oczyścił okolicę z wrogo nastawionych zwierząt. Gdy teren zostanie zabezpieczony, magistrowie zamierzają urządzić tu coś w rodzaju wysuniętej placówki przeciw Pladze.$B$BJeśli czegoś się nauczyłem jako uczeń, to przekazywania odpowiedzialności innym – zwłaszcza w sprawach, w których można stracić życie!$B$BJeśli cię to interesuje, sowicie ci zapłacę za zabicie większych wrzecionowych pająków i widmoszponów pustoszycieli na zachód i południe stąd.', 'Uczeń Vor\'el z Posiadłości Andilien na Widmowych Ziemiach chce, żebyś $gzabił:zabiła; 10 większych wrzecionowych pająków i 10 widmoszponów pustoszycieli.', '', 'Wróć do ucznia Vor\'ela w Posiadłości Andilien na Widmowych Ziemiach.', '', '', '', '', 0),
(9503, 'plPL', 'Zew wody', 'W równowadze z pozostałymi żywiołami woda jest źródłem i pokarmem wszystkich żywych istot. Daje i podtrzymuje życie, a wszystko, co istnieje, od niej zależy. Lecz gdy zostanie skażona, potrafi też życie zakończyć.$B$BMusimy ustalić, jak wielkie szkody już wyrządzono. Na południowym zachodzie leży jeden z takich skażonych zbiorników, nazywany Plugawą Sadzawką. Udaj się tam i wydobądź plugawą esencję z duchów wody, które zamieszkują sadzawkę.', 'Zbierz 6 plugawych esencji i zanieś je Aqueous przy Ukrytej Rafie na Wyspie Krwawej Mgły.', '', 'Wróć do Aqueous przy Ukrytej Rafie na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9504, 'plPL', 'Zew wody', 'Jest gorzej, niż można się było obawiać. Skażenie jest bardzo silne i jeśli nic go nie powstrzyma, może przeniknąć do prądów oceanicznych i rozprzestrzenić się po całym Azeroth!$B$BBy przeciwdziałać tej zarazie, będziemy potrzebować próbki najczystszej wody. Na nieskażonej części wyspy, na południowym wschodzie, są ruiny. Idź tam, gdzie mieszkają nagi Gniewnej Łuski, i zaczerpnij wody z ich fontanny.$B$BPobierz próbkę do tego bukłaka. Pospiesz się, $N!', 'Napełnij pusty bukłak, a następnie wróć do Aqueous przy Ukrytej Rafie na Wyspie Krwawej Mgły.', '', 'Wróć do Aqueous przy Ukrytej Rafie na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9508, 'plPL', 'Zew wody', 'Wiem już, skąd pochodzi skażenie. To produkt uboczny jakichś obłąkanych badań, a ty położysz im kres!$B$BTuż na południowy zachód od Plugawej Sadzawki leży niewielki obóz. Znajdziesz tam „badania” Tel\'athiona Nieczystego. To tam wytwarza plugastwo, które przesącza się do wód wyspy.$B$BUżyj czystej wody, którą $gzdobyłeś:zdobyłaś; z Jesionowej Kniei, by zniszczyć jego zapas beczek. To na pewno wywabi go z kryjówki.$B$BPołożymy temu kres!', 'Przynieś głowę Tel\'athiona Aqueous przy Ukrytej Rafie na Wyspie Krwawej Mgły.', '', 'Wróć do Aqueous przy Ukrytej Rafie na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9548, 'plPL', 'Skradziony sprzęt', 'Ciii! Mów ciszej i nie zwracaj na mnie uwagi.$B$BJeśli murloki mnie wykryją, eksperyment będzie zrujnowany! I tak już niebezpiecznie blisko było do zanieczyszczenia moich danych.$B$BWczoraj, gdy szukałem pożywienia, jeden z nich musiał podejść za blisko i odkrył mój obóz. Wróciłem akurat w porę, by zobaczyć, jak dwa z nich wynoszą skrzynię z większością mojego sprzętu! Na pewno trafiła do którejś z ich osad w okolicy, ale nie mogę ryzykować, że się zdradzę. Pomożesz mi?', 'Przynieś sprzęt Cloppera Clopperowi Wizbangowi, który ukrywa się w wyrzuconej na brzeg skorupie żółwia.', '', 'Wróć do Cloppera Wizbanga na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9549, 'plPL', 'Artefakty Czarnomułowych', 'Moje obserwacje i zapiski o murlokach z plemienia Czarnomułowych są bardzo pouczające, $N, ale to dopiero początek. Zamierzam wrócić do Żelaznej Kuźni z przedmiotami wytworzonymi dzięki prymitywnemu rzemiosłu Czarnomułowych.$B$BKłopot w tym, że Czarnomułowi cały czas noszą te przedmioty przy sobie, a ja nie mogę mieć ich krwi na sumieniu. Jeśli zechcesz pomóc mi zebrać idole, które noszą jasnowidze Czarnomułowych, i prymitywne noże ich wojowników i brzegowych napastników, nie będę pytać, jak je $gzdobyłeś:zdobyłaś;.', 'Przynieś 3 prymitywne idole murloków i 6 prymitywnych noży murloków Clopperowi Wizbangowi, który ukrywa się w wyrzuconej na brzeg skorupie żółwia.', '', 'Wróć do Cloppera Wizbanga na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9550, 'plPL', 'Mapa... dokąd?', 'Niezdarnie narysowana mapa nie zdradza niczego o swoim autorze, ale wygląda na to, że kreśliła ją drżąca ręka. Chwiejne linie i symbole przedstawiają niewielki pawilon z połamanymi kolumnami, położony na zachód od częściowo zatopionej wieży.$B$BJeśli wierzyć mapie, te ruiny leżą na wschodnim wybrzeżu wyspy. Nie masz pojęcia, co tam znajdziesz, ale dla twórcy mapy było to na tyle ważne, że postanowił to zaznaczyć.', 'Odnajdź pawilon opisany na mapie i poszukaj tego, co chciał zaznaczyć jej twórca.', '', '', '', '', '', '', 0),
(9557, 'plPL', 'Odczytanie księgi', 'Nie masz jak odczytać zawartości księgi, więc zastanawiasz się, kto mógłby pomóc ci oddzielić słowa autora od bazgrołów twórcy mapy.$B$BPrzypominasz sobie zbiór artefaktów z niezliczonych kultur, który ma Anachoreta Paetheus, i myślisz, że jego wprawne oko mogłoby pomóc odczytać treść księgi.', 'Zanieś starożytny dziennik Anachorecie Paetheusowi w Krwawej Strażnicy.', '', '', '', '', '', '', 0),
(9561, 'plPL', 'Słowa Nolkaia', 'Przekład jest gotowy, $N.$B$B<Anachoreta Paetheus wskazuje fragment tekstu na końcu przekładu.>$B$B„Wróg jest już niemal u bram. Zebraliśmy wszystkich ocalałych i wycofaliśmy się do świątyni na wschodzie. To ostatnie miejsce na wyspie, które naprawdę utrzymujemy, a wśród ocalałych panuje przeczucie, że tu przyjdzie nam stoczyć ostatni bój. Zakopałem na terenie świątyni kilka ostatnich rzeczy, które mi zostały, w nadziei, że ktoś je znajdzie i dowie się, co się tu wydarzyło”.', 'Odnajdź miejsce opisane w dzienniku Nolkaia i odkop jego dawno zakopane rzeczy.', '', '', '', '', '', '', 0),
(9567, 'plPL', 'Poznaj swego wroga', 'Dobrze widzieć kolejną nową twarz w Krwawej Strażnicy, $N. Choć najpilniejszym zagrożeniem są krwawe elfy, Wyspę Krwawej Mgły zamieszkują też inne złowrogie istoty.$B$BSzczególnie niepokoją nas satyry Nazzivusa. To plugawe, demoniczne stworzenia, które władają mroczną magią i żywią się skażeniem powstałym po katastrofie Exodaru.$B$BMusimy trzymać je w ryzach, ale najpierw musimy dowiedzieć się o nich więcej. Udaj się na południowy zachód do Nazzivian i dowiedz się, czego zdołasz, z ich groteskowego pomnika.', 'Odnajdź Pomnik Nazzivusa w Nazzivian i zdobądź glif z Pomnika Nazzivusa. Gdy zdobędziesz jeden z glifów, wróć do Obrończyni Aalesii w Krwawej Strażnicy.', '', 'Wróć do Obrończyni Aalesii w Krwawej Strażnicy na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9568, 'plPL', 'Do natarcia', 'Jest gorzej, niż sądziliśmy, $N. My, draenei, dobrze wiemy, co spotyka tych, którzy sprzedają duszę Płonącemu Legionowi w zamian za obietnice mocy i nieśmiertelności.$B$BSatyry na tej wyspie, Nazzivusowie, są potomkami tamtego pierwszego, wypaczonego stworzenia, które sprzymierzyło się z Legionem. Obawiam się, że znajdą sposób, by zwrócić przeciwko nam moc kryształów Exodaru.$B$BWidzisz, co zrobiły z tą ziemią. Wyobraź sobie, co satyry mogłyby zrobić z tymi kryształami. Udaj się na południowy zachód do Nazzivian i rozpocznij nasze natarcie!', 'Obrończyni Aalesia z Krwawej Strażnicy chce, żebyś $gzabił:zabiła; 10 satyrów Nazzivusa, 5 łotrów Nazzivusa i 5 zaprzysiężonych Spaczeniu z Nazzivusa.', '', 'Wróć do Obrończyni Aalesii w Krwawej Strażnicy na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9569, 'plPL', 'Powstrzymanie zagrożenia', 'Skoro satyry już wiedzą o naszej obecności, musimy dać im jasno do zrozumienia, że nie będziemy tolerować na tych ziemiach psów Płonącego Legionu.$B$BZbyt długo draenei uciekali przed Legionem i jego sługami, $N. Gdziekolwiek nas znaleźli, nie okazywali litości.$B$BNie możemy pozwolić, by satyry wykorzystały katastrofę Exodaru i obróciły skażone kryształy w broń. Udaj się na północ, do Axxarien, gdzie przebywa ich przywódca, zgładź go i odzyskaj skażone kryształy, które gromadzi!', 'Zabij 5 tropicieli cieni z Axxarien, 5 przywoływaczy piekieł z Axxarien i Zevraxa, a następnie zbierz 5 skażonych kryształów i wróć do Obrończyni Aalesii w Krwawej Strażnicy.', '', 'Wróć do Obrończyni Aalesii w Krwawej Strażnicy na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9574, 'plPL', 'Ofiary skażenia', 'Nasze przybycie na zawsze odmieniło Wyspę Krwawej Mgły. Katastrofa Exodaru rozrzuciła szczątki po całych wyspach i myślę, że zaczyna to szkodzić tutejszej przyrodzie.$B$BZanim będę pewna swoich wniosków, muszę przyjrzeć się temu z bliska. Wygląda na to, że kryształy najszybciej wpłynęły na drzewa, więc objawy najpewniej wystąpią u drzewców. Jeśli przyniesiesz mi próbki kory skażonych drzewców, będę mogła rozpocząć dokładne badania.', 'Przynieś 6 kawałków skrystalizowanej kory Morae w Krwawej Strażnicy.', '', 'Wróć do Morae w Krwawej Strażnicy na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9576, 'plPL', 'Naszyjnik Okrutnopłetwa', 'Oglądając prymitywnie wykonany wisior, zauważasz, że kryształ delikatnie pulsuje. Choć emituje niewiele światła, niemal czujesz, jak promieniuje od niego coś złego i nienaturalnego.$B$BNie wiesz, co mogło skłonić Okrutnopłetwa do zrobienia tego wisiora, ale znalezisko jest zbyt ważne, by je zignorować. Najlepiej pokaż je komuś w Krwawej Strażnicy.', 'Zanieś wisior z czerwonym kryształem Morae w Krwawej Strażnicy.', '', '', '', '', '', '', 0),
(9578, 'plPL', 'Poszukiwania Galaena', 'Często myślisz o swojej rodzinie, $N? Na pokładzie Exodaru było wiele rodzin, ale słyszałam o niewielu, które znów się odnalazły.$B$BJa sama szukam śladów mojego męża, Galaena, który był technikiem w Kriordzeniu. Wrak Kriordzenia leży na zachodzie i roi się tam od krwawych elfów!$B$BMuszę się dowiedzieć, co się stało z Galaenem! Nawet wieść o jego śmierci jest lepsza niż wieczna niepewność. Mój mąż powinien mieć na sobie wisior identyczny z moim; oba dostaliśmy w prezencie od mojej siostry.', 'Odszukaj Galaena, męża Morae.', '', '', '', '', '', '', 0),
(9579, 'plPL', 'Los Galaena', 'Na podstawie tego, co powiedziała ci Morae, nie masz jak rozpoznać w zwłokach Galaena, ale ubranie wygląda na rozdarte przez kogoś, kto szukał kosztowności.$B$BKrwawe elfy z okolicy zabrałyby z wraku wszystko, co cenne, w tym wysadzany klejnotami amulet Galaena.$B$BChoć jej mąż nie przeżył katastrofy, sądzisz, że Morae byłaby wdzięczna, gdybyś $godebrał:odebrała; krwawym elfom amulet jej męża.', 'Zanieś amulet Galaena Morae w Krwawej Strażnicy.', '', 'Wróć do Morae w Krwawej Strażnicy na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9580, 'plPL', 'Niedźwiedzie potrzeby', 'Jak zapewne $gzauważyłeś:zauważyłaś; podczas pobytu na Wyspie Krwawej Mgły, niewiele zostało tu nietkniętego przez nasze przybycie. Wyszkolenie i doświadczenie nauczyły mnie, że nawet z tego, co rodzi takie miejsce jak to, można zrobić użytek.$B$BPrzy tak skromnych zasobach musimy polegać na własnej pomysłowości. Uzupełniam nasze zapasy mięsem niedźwiedzi, które wędrują po wyspie. Odpowiednio przyrządzone nadaje się do bezpiecznego spożycia. Skoro i tak wyruszasz w teren, może pomożesz nam uzupełnić spiżarnię?', 'Przynieś 8 udźców starego niedźwiedzia brunatnego tropicielowi Lyceonowi w Krwawej Strażnicy.', '', 'Wróć do tropiciela Lyceona w Krwawej Strażnicy na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9581, 'plPL', 'Nauka z kryształów', 'Witaj w Krwawej Strażnicy, $N. Moją główną troską jest obrona tej placówki, ale nasi przywódcy w Exodarze powierzyli mi też wiele innych obowiązków.$B$BKłopot w tym, że na tak niebezpiecznej wyspie trudno wysyłać w teren liczne grupy badaczy. Potrzebuję kogoś, kto pobierze serię próbek kryształów z różnych miejsc na wyspie.$B$BPierwsza próbka musi pochodzić ze szczątków statku, w których zagnieździły się pustoszyciele, na południe od osady, po drugiej stronie mostu.', 'Zdobądź próbkę kryształu z miejsca uderzenia, używając kryształowego kilofa górniczego na krysztale z miejsca uderzenia, i zanieś ją Zwiastunowi Mikolaasowi w Krwawej Strażnicy.', '', 'Wróć do Zwiastuna Mikolaasa w Krwawej Strażnicy na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9584, 'plPL', 'Druga próbka', 'Skoro mamy już kryształ odniesienia, potrzebujemy próbek z bardziej niebezpiecznych rejonów wyspy, by skompletować zestaw, który wyślę do Exodaru.$B$BNastępna próbka musi pochodzić z kryształów, które kontrolują krwawe elfy w Lesie Ostrzy, na północny zachód od Krwawej Strażnicy. Doniesiono mi, że zmieniają kryształy i pozyskują je do jakiegoś magicznego urządzenia. Spróbuj znaleźć taki, którego jeszcze nie wbudowali w żadne ze swoich urządzeń, i wydobądź z niego próbkę.', 'Zdobądź próbkę zmienionego kryształu, używając kryształowego kilofa górniczego na zmienionym krysztale Krwawej Mgły, i zanieś ją Zwiastunowi Mikolaasowi w Krwawej Strażnicy.', '', 'Wróć do Zwiastuna Mikolaasa w Krwawej Strażnicy na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9585, 'plPL', 'Ostatnia próbka', 'Została już tylko jedna próbka, zanim będę mógł wysłać ten zestaw kryształów do Exodaru, $N. Ostatnia musi pochodzić z twierdzy satyrów w Axxarien, na północnym zachodzie.$B$BNie wiem, czego się spodziewać po tej próbce, ale na pewno będą na niej ślady skażenia. Pamiętaj, by odłupać odłamek z kryształu podobnego do tych, z których $gpobrałeś:pobrałaś; poprzednie próbki, bo inaczej nasi badacze nie będą mogli rzetelnie ich porównać.', 'Zdobądź próbkę kryształu z Axxarien, używając kryształowego kilofa górniczego na krysztale Axxarien, i zanieś ją Zwiastunowi Mikolaasowi w Krwawej Strażnicy.', '', 'Wróć do Zwiastuna Mikolaasa na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9594, 'plPL', 'Ślady Legionu', 'Ten fragment pancerza wykuto z głęboko czarnego metalu, który zdaje się pochłaniać światło. Choć nie wygląda na zaklęty, bije od niego niewątpliwe poczucie, że coś jest z nim nie tak.$B$BTakiego pancerza używa tylko jedna siła – Płonący Legion. Obecność Legionu w tym miejscu może oznaczać tylko jedno: zamierza on podburzyć satyry z wyspy przeciw draenei.$B$BUderz na miejscowe satyry, a potem wróć do Krwawej Strażnicy i pokaż ten fragment pancerza Obrończyni Aalesii.', 'Zabij 8 satyrów Nazzivusa i 8 zaprzysiężonych Spaczeniu z Nazzivusa, a następnie zanieś płytę pancerza Tzeraka Obrończyni Aalesii w Krwawej Strażnicy.', '', 'Wróć do Obrończyni Aalesii w Krwawej Strażnicy na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9603, 'plPL', 'Łóżka, bandaże i nie tylko', 'Witaj w Krwawej Strażnicy, $N. Wybacz ten nieład wokoło. Łatwo brać za pewnik proste rzeczy, jak w pełni urządzona i zaopatrzona karczma, dopóki nie trzeba jej zbudować z niczego.$B$BUdało nam się ocalić tę kapsułę na budynek, ale bez porządnego wyposażenia i środków pierwszej pomocy karczma jest niewiele lepsza od przerośniętego namiotu. Nurguni z Exodaru zaproponowała, że przygotuje paczkę na nasze najpilniejsze potrzeby, ale potrzebuję kogoś, kto dostarczy jej tę listę.', 'Zanieś listę Tophera Laando, mistrzowi hipogryfów w Krwawej Strażnicy.', '', '', '', '', '', '', 0),
(9620, 'plPL', 'Zaginiony zespół mierniczych', 'Odkąd urządziliśmy się tu, w Krwawej Strażnicy, wysyłam zespoły mierniczych, by sporządzić dokładniejsze mapy wyspy. Przeważnie wracały cało z potrzebnymi danymi, ale zespół, który wysłałem na wschód, do ruin, nie złożył meldunku.$B$BMartwię się, co mogło ich spotkać, ale nie mogę wysłać po nich kolejnej grupy ludzi. Odnajdź ich, $N, i udziel im wszelkiej pomocy, jakiej potrzebują, by wrócić z danymi pomiarowymi.', 'Zwiastun Mikolaas chce, żebyś $godnalazł:odnalazła; zespół mierniczych, który wysłał do Ruin Loreth\'Aran, i $gpomógł:pomogła; im, jak tylko zdołasz.', '', '', '', '', '', '', 0),
(9624, 'plPL', 'Ulubiony przysmak', 'Dokonałem wspaniałego odkrycia, $N. Na nieskażonej części wyspy rośnie niezwykły owoc zwany piaskową gruszką. Można je znaleźć u stóp drzew.$B$BPiekę z nich placki, ale jeśli nie uważam, elekki zaczynają podchodzić i podkradać mi owoce. Zacząłem zbierać tyle, by starczyło też dla zwierząt, ale moje zapasy się skończyły, a znów nabrałem ochoty na placek. Czy pomożesz mi zebrać owoce na kolejną porcję placków? Obiecuję, że się podzielę!', 'Aonar z Przeprawy Kessela chce, żebyś $gprzyniósł:przyniosła; mu 10 piaskowych gruszek.', '', 'Wróć do Aonara na Wybrzeżu Berylu na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9628, 'plPL', 'Ratowanie danych', 'Na pomoc kartografom w dokończeniu misji jest już za późno, ale wygląda na to, że zebrali dane, na które czekał Zwiastun Mikolaas. Kryształu z wynikami pomiarów nie było w ich splądrowanych tobołach, więc musi być w rękach nag Gniewnej Łuski.$B$BWiesz, że Zwiastuna Mikolaasa zasmuci strata zespołu, ale na pewno będzie chciał odzyskać dane pomiarowe.', 'Zdobądź kryształ z danymi pomiarowymi od nag Gniewnej Łuski w pobliżu martwych kartografów i zanieś go Zwiastunowi Mikolaasowi w Krwawej Strażnicy.', '', 'Wróć do Zwiastuna Mikolaasa w Krwawej Strażnicy na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9629, 'plPL', 'Złap i wypuść', 'Czarnomułowi z południowo-zachodniego wybrzeża to ciekawe stworzenia. Pod pewnymi względami zachowują się, jakby ledwie mieli świadomość, pod innymi zaś wykazują zdumiewający stopień zorganizowania.$B$BMam na ten temat kilka teorii, ale do niedawna nie miałam jak ich sprawdzić. Opracowałam metodę, która pozwoli mi śledzić wybrane murloki, nie wyrządzając im trwałej krzywdy ani nie zakłócając ich naturalnych zachowań. Jeśli pomożesz mi je oznakować, chętnie zapłacę ci za pomoc.', 'Morae z Krwawej Strażnicy chce, żebyś „$goznakował:oznakowała;” 6 zwiadowców Czarnomułowych znakownikiem murloków.', '', 'Wróć do Morae w Krwawej Strażnicy na Wyspie Krwawej Mgły.', 'Oznakowani zwiadowcy Czarnomułowych', '', '', '', 0),
(9634, 'plPL', 'Obce drapieżniki', 'Podczas naszych wędrówek nauczyliśmy się jednego: przenosząc zwierzęta z jednego świata na inny, trzeba zachować najwyższą ostrożność. Gdy Exodar się rozbił, przewoził okazy różnych gatunków z Rubieży, w tym owadziego drapieżnika zwanego pustoszycielem.$B$BCzęść okazów przepadła, ale wiele innych przeżyło i zdziczało. Jeśli nie będziemy trzymać ich w ryzach, zaburzą naturalną równowagę na wyspach.$b$bPustoszyciele znajdziesz na zachód od Przeprawy Kessela, w pobliżu wybrzeża.', 'Zabij 10 piskląt z Krwawej Mgły, a następnie wróć do Vorkhana Pasterza Elekków przy Przeprawie Kessela na Wyspie Krwawej Mgły.', '', 'Wróć do Vorkhana Pasterza Elekków na Wybrzeżu Berylu na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9641, 'plPL', 'Napromieniowane odłamki kryształów', 'Katastrofa Exodaru rozrzuciła kawałki skażonych kryształów po całej Wyspie Krwawej Mgły, zatruwając wodę i ziemię.$B$BZaczęliśmy nawet znajdować odłamki kryształów w mięsie zwierząt ubitych na pożywienie. Odkryłem sposób, by oczyścić te odłamki i przerobić je na sprawne kryształy, więc jeśli przyniesiesz mi dość odłamków, wymienię je na jeden z moich gotowych kryształów. Jak dotąd znajdowałem odłamki w ciałach niedźwiedzi, pustoszycieli, trzepotków i drzewców zamieszkujących skażoną część wyspy.', 'Obrońca Boros z Krwawej Strażnicy chce, żebyś $gprzyniósł:przyniosła; mu 10 napromieniowanych odłamków kryształu.', '', 'Wróć do Obrońcy Borosa w Krwawej Strażnicy na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9642, 'plPL', 'Kolejne napromieniowane odłamki kryształów', '', '', '', 'Wróć do Obrońcy Borosa na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9643, 'plPL', 'Pnącza dusicieli', 'Dobry leśnik korzysta z każdego dostępnego zasobu, $N. Nawet najdziwaczniejsze stworzenia mają cechy, które możemy obrócić na naszą korzyść.$B$BKrwawa Strażnica jest nieustannie atakowana przez Słoneczne Jastrzębie, więc szukamy różnych naturalnych sposobów obrony, w tym pułapek. Cierniste pnącza smagaczy doskonale nadają się do budowy pułapek, które mam na myśli. Połączenie ostrych kolców i śmiercionośnej toksyny powali nieostrożnych napastników. Przynieś mi pnącza zmutowanych dusicieli, żebym mógł zacząć pracę.', 'Tropiciel Lyceon z Krwawej Strażnicy chce, żebyś $gprzyniósł:przyniosła; mu 6 ciernistych pnączy dusiciela.', '', 'Wróć do tropiciela Lyceona w Krwawej Strażnicy na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9646, 'plPL', 'POSZUKIWANY: Śmiertelny Pazur', 'Z rozkazu Zwiastuna Mikolaasa: nagroda w wysokości 18 sztuk srebra zostanie wypłacona śmiałkowi, który przyniesie dowód śmierci grasującego niedźwiedzia Śmiertelnego Pazura.$B$BŚmiertelny Pazur jest niezwykle niebezpieczny i odpowiada za zabicie zespołu mierniczych na wybrzeżu na północny zachód od Krwawej Strażnicy. Podróżnym zaleca się omijanie tej okolicy.', 'Przynieś łapę Śmiertelnego Pazura Zwiastunowi Mikolaasowi w Krwawej Strażnicy.', '', 'Wróć do Zwiastuna Mikolaasa na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9647, 'plPL', 'Przetrzebienie trzepotków', 'Gdy pierwszy raz natknęliśmy się na trzepotki, wykazywały niewiele oznak mutacji. W miarę jak skażenie się pogłębiało, ćmy i inne gatunki zaczęły zdradzać objawy zatrucia.$B$BDoszło do tego, że niszczą niemal wszystko, z czym się zetkną. Potęgują szkody wyrządzane przez odłamki kryształów, które rozrzuciła katastrofa Exodaru. Nie mamy wyboru, musimy przetrzebić ich populację na ziemiach na północ od Krwawej Strażnicy.', 'Tropiciel Lyceon z Krwawej Strażnicy chce, żebyś $gzabił:zabiła; 10 królewskich niebieskich trzepotków.', '', 'Wróć do tropiciela Lyceona w Krwawej Strażnicy na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9648, 'plPL', 'Grzybowa menażeria z Mac\'Aree', 'Czy wiesz, że zbieranie grzybów jest o wiele groźniejsze niż ich jedzenie? Grzybiarze narażają się na wiele niewiadomych – nie licząc zagrożeń ze strony dzikich zwierząt!$B$BLecz czym byłoby życie bez odrobiny niebezpieczeństwa? Potrzebuję grzybów do mojej kolekcji. W tych niezbadanych ostępach znajdziesz cztery rodzaje: wodnego sromotnika, krwawego grzyba, zgubnego wielozarodnika i grzyba ze spaczonej szyszki. Każdy z nich rośnie tylko w innym zakątku Krwawej Mgły. Przynieś mi je.', 'Jessera z Mac\'Aree w Krwawej Strażnicy prosi o 1 wodnego sromotnika, 1 krwawego grzyba, 1 zgubnego wielozarodnika i 1 grzyba ze spaczonej szyszki.', '', 'Wróć do Jessery z Mac\'Aree w Krwawej Strażnicy na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9649, 'plPL', 'Łzy Ysery', 'Dobrze cię znowu widzieć, $N! Poprzednie zadanie, które ci zleciłem, $gwykonałeś:wykonałaś; wyjątkowo sprawnie. Może zainteresuje cię kolejne?$B$BNa północnym wschodzie leży Wyspa Blizny Żmija, siedlisko rzadkiego gatunku grzyba zwanego łzą Ysery – od zielonych smocząt, które zamieszkują wyspę. Potrzebuję tylko kilku okazów tego grzyba, ale muszę cię ostrzec, że mieszkańcy wyspy nie witają gości życzliwie. Stąpaj ostrożnie.$B', 'Jessera z Mac\'Aree w Krwawej Strażnicy prosi o 2 łzy Ysery.', '', 'Wróć do Jessery z Mac\'Aree w Krwawej Strażnicy na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9663, 'plPL', 'Rajd Kessela', 'Przybywasz w samą porę, $N. W ostatnim tygodniu aktywność krwawych elfów w tej okolicy się podwoiła. Nasi agenci donieśli, że krwawe elfy, które nazywają siebie Słonecznymi Jastrzębiami, planują wkrótce uderzyć na Lazurową Mgłę. Musisz przekazać ostrzeżenie naszym sojusznikom i rodakom.$B$BOstrzeż najwyższego wodza Cichą Sosnę w Warowni Cichej Sosny, Egzarchę Menelaousa w Lazurowej Strażnicy i admirała Odesyusa w Przystani Odesyusa.$B$BLiczy się każda chwila, więc pożyczam ci mojego elekka. Pilnuj, żeby nie wszedł do wody.', 'Kessel z Przeprawy Kessela chce, żebyś $gostrzegł:ostrzegła; najwyższego wodza Cichą Sosnę w Warowni Cichej Sosny, Egzarchę Menelaousa w Lazurowej Strażnicy i admirała Odesyusa w Przystani Odesyusa przed nadciągającą inwazją krwawych elfów. Gdy wykonasz zadanie, wróć do Kessela. Masz 15 minut. (Pilnuj, żeby elekk nie wszedł do wody).', '', 'Wróć do Kessela na Wyspie Krwawej Mgły.', 'Najwyższy wódz Cicha Sosna ostrzeżony', 'Egzarcha Menelaous ostrzeżony', 'Admirał Odesyus ostrzeżony', '', 0),
(9666, 'plPL', 'Pokaz siły', '$GWidziałeś:Widziałaś; wężoludzi? Tych, którzy nazywają siebie nagami?$B$B<Kessel spluwa.>$B$BLedwie trzy noce temu ośmielili się podejść pod ten obóz pod osłoną ciemności. Wyobrażasz sobie zuchwałość tych prymitywnych bestii?$B$BMusisz przekazać wiadomość ich przywódcom, $N. Na północnym wschodzie leży Leże Gniewnej Łuski, siedziba Lorda Xiza. Odnajdź go, zabij na miejscu i przebij jego trupa tym sztandarem.$B$BNiech ogarnia ich strach, ilekroć ujrzą nasze barwy!', 'Kessel z Przeprawy Kessela na Wyspie Krwawej Mgły chce, żebyś $gzabił:zabiła; Lorda Xiza w Leżu Gniewnej Łuski i $gprzebił:przebiła; jego ciało draenejskim sztandarem.', 'Pokaz siły', 'Wróć do Kessela przy Przeprawie Kessela na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9667, 'plPL', 'Ratunek dla księżniczki Cichej Sosny', 'Pomóż mi, $N! Szczecinołapi mnie pojmali i chcą złożyć mnie w ofierze swoim plugawym bogom!$B$BNajwyższy wódz Szczecinołap ma klucz do klatki. Żeby zmusić go do wyjścia, musisz wybić złe furbolgi ze Szczecinołapych, które zamieszkują enklawę dwa obozy na zachód od tego. Jeśli zabijesz ich wystarczająco wielu, na pewno przyjdzie się zemścić! Gdy się pojawi, zabij go i zdobądź klucz!$B$BMój ojciec sowicie cię nagrodzi, jeśli mnie uratujesz!', 'Uwolnij księżniczkę Cichą Sosnę z klatki, a następnie porozmawiaj z ambasadorem Cichej Sosny Frasaboo w Krwawej Strażnicy.$B$BMusisz zabić najwyższego wodza Szczecinołapa, by zdobyć klucz do klatki.', '', 'Wróć do ambasadora Cichej Sosny Frasaboo w Krwawej Strażnicy na Wyspie Krwawej Mgły.', 'Księżniczka Cicha Sosna uratowana', '', '', '', 0),
(9668, 'plPL', 'Zamelduj się u Egzarchy Admetiusa', 'Żołnierz Ręki Argusa musi być posłuszny, odważny, inteligentny, a nade wszystko honorowy. Być może jeszcze wykażesz się niektórymi z tych cech, $N.$B$BZamelduj się u Egzarchy Admetiusa w Krwawej Strażnicy, jeśli wciąż chcesz wstąpić do Ręki. On i jego podwładni będą dalej szkolić cię w rzemiośle draenejskiego żołnierza.$B$BI zapamiętaj jedno, $N: honorowi ludzie nie zawsze postępują honorowo. Czasem nie mogą.$B$BKrwawą Strażnicę znajdziesz dalej tą drogą, na północy.', 'Porozmawiaj z Egzarchą Admetiusem w Krwawej Strażnicy.', '', '', '', '', '', '', 0),
(9669, 'plPL', 'Zaginiona ekspedycja', 'Mniej więcej tydzień temu razem z moim zespołem badawczym przemierzaliśmy dzikie ostępy zachodniej części Krwawej Mgły, gdy napadły nas krwiożercze pająki. Skutki skażenia kryształami były aż nadto widoczne – pająki były ogromne i niezwykle agresywne.$B$BMnie udało się uciec, ale mój zespół nie miał tyle szczęścia. Nie możemy pozwolić, by inni podzielili ich los. Udaj się na zachód, na Przełęcz Bursztynowej Sieci, i zniszcz pająki oraz ich matriarchę, Zarakh.', 'Zabij 8 prządek Mgły, 8 pijawek Mgły i ich przywódczynię, Zarakh. Gdy wykonasz zadanie, wróć do Achelusa w Krwawej Strażnicy.', '', 'Wróć do Achelusa w Krwawej Strażnicy na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9670, 'plPL', 'Żyją! Chyba...', 'To była krwawa jatka, $N. Wpadliśmy w zasadzkę dużej gromady tych pająków. Ich pramatka spadła na nas z niewiarygodną szybkością i owinęła nas w kokony.$B$BGdy już byliśmy oplątani siecią, zaczęła składać obok nas jaja. Mieliśmy być pokarmem dla jej młodych! POKARMEM!$B$BUdało mi się wyciąć sobie drogę i uciec, ale nie zostawię pozostałych. Jak dotąd nie zdołałem nawet zbliżyć się do przełęczy. Pomożesz mi?$B$BZniszcz te kokony! Miejmy nadzieję, że ktoś z naszego zespołu jeszcze żyje!$B', 'Badacz Cornelius prosi, żebyś $guwolnił:uwolniła; 5 badaczy z ekspedycji.', '', 'Wróć do badacza Corneliusa na Przełęczy Bursztynowej Sieci na Wyspie Krwawej Mgły.', 'Uwolniony badacz z ekspedycji', '', '', '', 0),
(9671, 'plPL', 'Pilna przesyłka', '', '', '', '', '', '', '', '', 0),
(9674, 'plPL', 'Nagi przeklęte krwią', 'Mówi się, że gdy świat został rozdarty, ta kraina płakała najgłośniej. To tutaj tysiące nocnych elfów przepadło w niebycie, a na ich miejsce powstały straszliwe istoty pełne nienawiści – nagi.$B$BPosłuszne swej wypaczonej królowej, Aszarze, niszczyły wszystko, co ośmieliło się zapuścić na ich morze. I tak było przez tysiące lat – aż do teraz.$B$BNa początek trzeba usunąć z rafy nagi przeklęte krwią.', 'Kapitan Edward Hanes z Wyspy Blizny Żmija chce, żebyś $gzabił:zabiła; 10 nag przeklętych krwią.$B', '', 'Wróć do kapitana Edwarda Hanesa na Wyspie Blizny Żmija u wybrzeży Wyspy Krwawej Mgły.', '', '', '', '', 0),
(9682, 'plPL', 'Pozbawieni nadziei...', 'Na skalnej półce rafy, głębiej niż tam, gdzie $gnatrafiłeś:natrafiłaś; na nagi przeklęte krwią, znajdziesz pozbawionych nadziei: podróżników przeklętych krwią, duchy tych, których zabrała krwawa klątwa.$B$BŻałuję, że muszę cię o to prosić... ale trzeba ich zniszczyć, a ich przeklęte powłoki przynieść do mnie.$B$BIch dusze muszą zaznać spokoju. Wróć, gdy wykonasz zadanie, a powierzę ci ostatnie.', 'Kapitan Edward Hanes z Wyspy Blizny Żmija chce, żebyś $godzyskał:odzyskała; 4 dusze przeklęte krwią.', '', 'Wróć do kapitana Edwarda Hanesa na Wyspie Blizny Żmija u wybrzeży Wyspy Krwawej Mgły.', '', '', '', '', 0),
(9683, 'plPL', 'Koniec krwawej klątwy', 'Na południu znajdziesz Wyspę Krwawej Klątwy. Na jej szczycie stoi kapliczka ku czci ukochanej królowej nag, Aszary. Zniszcz posąg – spal jej podobiznę! To z pewnością ściągnie gniew Atopha, przywódcy przeklętych krwią.$B$BZabij Atopha i wróć do mnie!', 'Kapitan Edward Hanes z Wyspy Blizny Żmija chce, żebyś $gzniszczył:zniszczyła; Posąg królowej Aszary i $gzabił:zabiła; Atopha Przeklętego Krwią.', '', 'Wróć do kapitana Edwarda Hanesa na Wyspie Blizny Żmija u wybrzeży Wyspy Krwawej Mgły.', '', '', '', '', 0),
(9687, 'plPL', 'Przywrócenie świętości', 'Niedawno na brzegach tej wyspy pojawiły się lunozwierze z tych okolic, niegdyś tak spokojne. Jeden po drugim przychodziły kraść kości poległych smoków. Nie wiem, co mogło tak wzburzyć te stworzenia ani po co im kości zmarłych, lecz przez to świętokradztwo duchy stada nie mogą zaznać spokoju.$B$BNa zachodzie, po drugiej stronie Karmazynowego Zasięgu, znajdziesz Grań Wściekłych Piór. Wyrusz do obozowisk lunozwierzy i odzyskaj skradzione smocze kości.', 'Książę Toreth z Wyspy Blizny Żmija chce, żebyś $godzyskał:odzyskała; 8 smoczych kości.', '', 'Wróć do księcia Toretha na Wyspie Blizny Żmija u wybrzeży Wyspy Krwawej Mgły.', '', '', '', '', 0),
(9688, 'plPL', 'W głąb Snu', 'Smocze pisklęta, które widzisz na tej wyspie, to niespokojne duchy Zielonego Stada. Tak jak ja są przykute do tej ziemi i nie mogą odejść na miejsce wiecznego spoczynku w Szmaragdowym Śnie.$B$BOdzyskanie kości poległych nieco je uspokoiło, lecz musisz zrobić coś więcej.$B$BZniszcz ich eteryczne postaci. Nie mogę opuścić tego miejsca, dopóki to się nie dokona. Trzeba je uwolnić!', 'Książę Toreth z Wyspy Blizny Żmija prosi, żebyś $gzabił:zabiła; 5 wirydianowych piskląt i 5 wirydianowych młodych.', '', 'Wróć do księcia Toretha na Wyspie Blizny Żmija u wybrzeży Wyspy Krwawej Mgły.', '', '', '', '', 0),
(9689, 'plPL', 'Brzytwopaszczy', 'Wielu smoków z Czarnego Stada zginęło podczas tamtych ataków. Jeden z nich, porucznik samego Śmiercioskrzydłego, wciąż nawiedza to miejsce. Jeśli spojrzysz w niebo, zobaczysz jego widmową postać krążącą w przestworzach. Jego nienawiść jest tak wielka, że trwa tu nawet po śmierci.$B$BZanieś kości, które wcześniej dla mnie $gzebrałeś:zebrałaś;, na szczyt góry na tej wyspie i złóż je na wiecznie płonącym stosie. To powinno dać Brzytwopaszczemu znak, by zniżył lot. Gdy to zrobi, zabij jego nieumarłą postać.', 'Książę Toreth z Wyspy Blizny Żmija prosi, żebyś $gzabił:zabiła; Brzytwopaszczego.', '', 'Wróć do księcia Toretha na Wyspie Blizny Żmija u wybrzeży Wyspy Krwawej Mgły.', '', '', '', '', 0),
(9693, 'plPL', 'Czym jest dla mnie Argus', 'Czym jest dla ciebie Argus, $N? Wielu draenei pewnie nie zna albo nie pamięta naszej ojczystej planety. To tam oddzieliliśmy się od man\'ari – wypaczonych, demonicznych odbić nas samych, „obdarowanych” przez Sargerasa. Czy też, jak sami się nazywają, eredarów.$B$BEredar... to słowo kiedyś coś znaczyło.$B$B<Admetius cmoka, jakby smakował to słowo.>$B$BObrzydliwe.$B$BNie traćmy więcej czasu. Odszukaj Obrońcę Borosa i rozpocznij szkolenie.', 'Egzarcha Admetius z Krwawej Strażnicy kazał ci porozmawiać z Obrońcą Borosem.', '', '', '', '', '', '', 0),
(9694, 'plPL', 'Krwawa Strażnica', 'Krwawa Strażnica to jedna z dwóch wysuniętych baz Ręki Argusa. W drugiej, Lazurowej Strażnicy, już $gbyłeś:byłaś; – na Krwawej Mgle sprawy mają się zupełnie inaczej. Gdy tu przybyliśmy, ta kraina była równie piękna jak Lazurowa Mgła. Nazwaliśmy ją nawet Srebrną Wichurą, ale teraz szerzy się tu choroba, a co gorsza, krwawe elfy, z którymi walczyliśmy na pokładzie Exodaru, przeżyły katastrofę. I tu dochodzę do twojego zadania: wyrusz na północny zachód, do Lasu Ostrzy, i zlikwiduj wszystkie krwawe elfy, jakie tam znajdziesz.', 'Obrońca Boros z Krwawej Strażnicy chce, żebyś $gzabił:zabiła; 10 szpiegów Słonecznych Jastrzębi.', '', 'Wróć do Obrońcy Borosa w Krwawej Strażnicy na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9695, 'plPL', 'Rozkaz Króla Słońca', 'Ten dokument wygląda na ważny. Niestety jest napisany po thalasyjsku, w języku, którego nie rozumiesz.$B$BMoże Obrońca Boros będzie wiedział, co zrobić z tym listem.', 'Zanieś rozkaz Króla Słońca Obrońcy Borosowi w Krwawej Strażnicy.\n', '', '', '', '', '', '', 0),
(9696, 'plPL', 'Przekład...', 'Nasza główna śledcza, Elysia, biegle włada thalasyjskim. Zanieś jej dokument i zobacz, co powie.', 'Zanieś depeszę Słonecznych Jastrzębi Śledczej Elysii w Krwawej Strażnicy.', '', '', '', '', '', '', 0),
(9700, 'plPL', 'Strzelam magią w ciemność', 'Velen twierdzi, że jeśli krwawe elfy otwierały szczeliny między tą wyspą a Rubieżą, w miejscach, gdzie otwarto portale, musiały zostać ślady lub anomalie. Przeszukaj wyspę i znajdź miejsca, w których występują takie anomalie.$B$BUważaj, $N – niektóre z tych anomalii to istoty z samej Pustki. Jeśli natrafisz na anomalie Pustki, zabij je! Przekaż mi wszelkie nowe informacje, jakie zdobędziesz. Zacznij poszukiwania na północy, w pobliżu Tłoku Osnowy.$B', 'Obrońca Boros z Krwawej Strażnicy chce, żebyś $godnalazł:odnalazła; miejsce słonecznego portalu i $gzabił:zabiła; 5 anomalii Pustki.', 'Miejsce słonecznego portalu potwierdzone', 'Wróć do Obrońcy Borosa w Krwawej Strażnicy na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9703, 'plPL', 'Kriordzeń', 'Inni badają tropy prowadzące do słonecznych portali, $N. Ty skup się na bieżącym zadaniu.$B$BBoros otrzymał meldunki o kolejnym miejscu katastrofy. Jak się później okazało, to w rzeczywistości kriordzeń Exodaru – składowisko kapsuł, dokładnie takich jak te, z których my, draenei, wyczołgaliśmy się w Dolinie Ammen.$B$BPrzechowywano tam też zapasy medyczne. Udaj się do Kriordzenia, na zachód od Krwawej Strażnicy. Poszukaj zapasów i ocalałych.$B', 'Obrońca Kuros z Krwawej Strażnicy chce, żebyś $godzyskał:odzyskała; 12 skrzynek zapasów medycznych.', '', 'Wróć do Obrońcy Kurosa w Krwawej Strażnicy na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9706, 'plPL', 'Dziennik Galaena – los Obrońcy Saruana', 'Ręce ci drżą, gdy podnosisz księgę. Kuros musi się dowiedzieć o tej tragedii. Zanieś mu księgę.', 'Zanieś dziennik Galaena Obrońcy Kurosowi w Krwawej Strażnicy.$B', '', '', '', '', '', '', 0),
(9711, 'plPL', 'Matis Okrutny', 'Matis stanie przed sądem, $N, a ja chcę, żeby to właśnie ty go $godnalazł:odnalazła; i $gsprowadził:sprowadziła; przed Triumwirat.$B$BPrzeszukaj wyspę i znajdź tego mordercę. Gdy go znajdziesz, użyj tej rakietnicy. Gdy moi tropiciele zobaczą racę, przybędą pomóc pojmać Matisa. Wróć do mnie, gdy zostanie schwytany.', 'Obrońca Kuros z Krwawej Strażnicy chce, żebyś $gpojmał:pojmała; Matisa Okrutnego.', 'Matis Okrutny schwytany', 'Wróć do Obrońcy Kurosa w Krwawej Strażnicy na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9740, 'plPL', 'Słoneczna Brama', 'Dzięki tobie i twojej pracy moi zwiadowcy zdołali odnaleźć Słoneczną Bramę. Elfy nie trzymają portalu w jednym miejscu, żeby w każdej chwili móc go przenieść. Dlatego miejsce, które $gzbadałeś:zbadałaś;, było puste.$B$BSiła takiego rozwiązania jest zarazem jego największą słabością. Słoneczną Bramę stabilizują kontrolery portalu. Jeśli zniszczymy kontrolery, portal będzie nasz i będziemy mogli go zniszczyć. Słoneczna Brama stoi teraz na zachód stąd, na południe od Zwoju Wektorowego. Odszukaj ją i zniszcz!', 'Obrońca Aesom z Krwawej Strażnicy chce, żebyś $gzniszczył:zniszczyła; Słoneczną Bramę.', '', 'Wróć do Obrońcy Aesoma w Krwawej Strażnicy na Wyspie Krwawej Mgły.', 'Słoneczna Brama zniszczona', '', '', '', 0),
(9741, 'plPL', 'Zwierzaki Pustki', 'Kilka dni temu Aesom wysłał mój oddział na zwiad, żeby odnaleźć Słoneczną Bramę. Chyba nie muszę mówić, że ją znaleźliśmy...$B$B<Loryi wskazuje na Jorli.>$B$BCokolwiek te głupie elfy przerzucają przez portal, uwalnia to energię Pustki. W okolicy roi się od zwierzaków Pustki.$B$BMusimy je zniszczyć, zanim zdążą wyrosnąć na anomalie Pustki. Źródło tych stworzeń znajdziesz na południowy zachód stąd, w pobliżu Słonecznej Bramy. Zabij je, a potem zamelduj się u Aesoma.', 'Zabij 12 zwierzaków Pustki i zamelduj się u Obrońcy Aesoma w Krwawej Strażnicy.$B', '', 'Wróć do Obrońcy Aesoma w Krwawej Strażnicy na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9746, 'plPL', 'Granice fizycznego wyczerpania', 'Zwycięstwo jest na wyciągnięcie ręki, $N. Skoro odkryliśmy Słoneczną Bramę, wkrótce ich linie zaopatrzenia zostaną całkowicie odcięte. Teraz czas przerzedzić ich szeregi.$B$BNa zachodzie znajdziesz liczne obozy Słonecznych Jastrzębi. Piromanci i obrońcy Słonecznych Jastrzębi zajmują większość tego terenu. Znajdź ich, zabij i wróć do mnie.', 'Obrońca Aesom z Krwawej Strażnicy chce, żebyś $gzabił:zabiła; 10 piromantów Słonecznych Jastrzębi i 10 obrońców Słonecznych Jastrzębi.$B', '', 'Wróć do Obrońcy Aesoma w Krwawej Strażnicy na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9748, 'plPL', 'Nie pij tej wody', 'Nasi szamani twierdzą, że skażenie źródeł mocno wzburzyło żywioły wody. Wiemy, że rdzeń energetyczny Exodaru utkwił w górze na zachodzie. Musi z niego wyciekać do wód niestabilny płyn! Potrzebuję więcej informacji.$B$B<Aesom wskazuje flaszkę i kiwa głową.>$B$BWeź tę flaszkę i idź plażą na północ, aż dotrzesz do miejsca, gdzie rzeki Krwawej Mgły uchodzą do oceanu. Pobierz stamtąd próbkę i wróć do mnie.', 'Obrońca Aesom z Krwawej Strażnicy chce, żebyś $gpobrał:pobrała; próbkę wody z Krwawej Mgły do flaszki na próbki wody.', '', 'Wróć do Obrońcy Aesoma w Krwawej Strażnicy na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9749, 'plPL', 'Żyją! Chyba...', 'To była krwawa jatka, $N. Wpadliśmy w zasadzkę dużej gromady tych pająków. Ich pramatka spadła na nas z niewiarygodną szybkością i owinęła nas w kokony.$B$BGdy już byliśmy oplątani siecią, zaczęła składać obok nas jaja. Mieliśmy być pokarmem dla jej młodych! POKARMEM!$B$BUdało mi się wyciąć sobie drogę i uciec, ale nie zostawię pozostałych. Jak dotąd nie zdołałem nawet zbliżyć się do przełęczy. Pomożesz mi?$B$BZniszcz te kokony! Miejmy nadzieję, że ktoś z naszego zespołu jeszcze żyje!$B', 'Badacz Cornelius prosi, żebyś $guwolnił:uwolniła; 5 badaczy z ekspedycji.', '', 'Wróć do badacza Corneliusa na Przełęczy Bursztynowej Sieci na Wyspie Krwawej Mgły.', 'Uwolniony badacz z ekspedycji', '', '', '', 0),
(9750, 'plPL', 'UNUSED Pilna przesyłka', '', '', '', '', '', '', '', '', 0),
(9753, 'plPL', 'Co wiemy...', 'W ostatnich dniach wiele dowiedzieliśmy się o naszych wrogach. Krwawymi elfami dowodzi istota zwana Sironas, a ich celem jest nasza zguba. Chcą zniewolić O\'rosa i odzyskać kontrolę nad Exodarem.$B$BChwała Światłości, niszcząc Słoneczną Bramę, odcięliśmy im linię zaopatrzenia. Niestety wciąż używają skażenia ze Zwoju Wektorowego, by zatruwać ziemię, i obracają na swoją korzyść mutagenne właściwości opadu.$B$BWiedząc to, Admetius opracował plan. Odszukaj go.', 'Porozmawiaj z Egzarchą Admetiusem w Krwawej Strażnicy.', '', '', '', '', '', '', 0),
(9755, 'plPL', '', 'Nasze próby przesłuchań spełzły na niczym, $N. Tortury – rzecz jasna – nie wchodzą w grę. Potrzebujemy draenei, który przeniknie do ich szeregów.$B$BMogę rzucić na ciebie zaklęcie, dzięki któremu będziesz wyglądać jak krwawy elf i mówić jak oni. Podstępem może uda nam się wydobyć z pojmanych agentów potrzebne informacje.$B$BW tym przebraniu wyciągnij z więźniów wszystko, co się da.$B$BI jeszcze jedno, $N: nie opuszczaj Krwawej Strażnicy w przebraniu, bo zaklęcie przestanie działać.\n', 'Porozmawiaj ze schwytanym agentem Słonecznych Jastrzębi w Krwawej Strażnicy i zdobądź informacje o Słonecznych Jastrzębiach. Po wykonaniu zadania wróć do Egzarchy Admetiusa.\n', 'Zdobyto informacje o Słonecznych Jastrzębiach', '', '', '', '', '', 0),
(9756, 'plPL', 'Czego nie wiemy...', 'Nasze próby przesłuchań spełzły na niczym, $N. Tortury – rzecz jasna – nie wchodzą w grę. Potrzebujemy draenei, który przeniknie do ich szeregów.$B$BMogę rzucić na ciebie zaklęcie, dzięki któremu będziesz wyglądać jak krwawy elf i mówić jak oni. Podstępem może uda nam się wydobyć z pojmanego agenta potrzebne informacje.$B$BW tym przebraniu wyciągnij z więźnia wszystko, co się da.$B$BI jeszcze jedno, $N: nie opuszczaj Krwawej Strażnicy w przebraniu, bo zaklęcie przestanie działać.', 'Porozmawiaj ze schwytanym agentem Słonecznych Jastrzębi w Krwawej Strażnicy i zdobądź informacje o Słonecznych Jastrzębiach. Gdy wykonasz zadanie, wróć do Egzarchy Admetiusa.', '', 'Wróć do Egzarchy Admetiusa na Wyspie Krwawej Mgły.', 'Uzyskano informacje o Słonecznych Jastrzębiach', '', '', '', 0),
(9759, 'plPL', 'Koniec ich świata', 'Nie przyjmuj tego zadania, jeśli ci życie miłe. Widzisz ten olbrzymi rdzeń energetyczny, który sterczy tam ze zbocza góry? Kto się tego podejmie, będzie musiał przebić się przez tę górę, walcząc z armią Słonecznych Jastrzębi i osłaniając mnie, gdy będę szykować rdzeń do wysadzenia. Gdzieś tam na górze jest też eredarka Sironas.$B$BNie pomyślę o tobie gorzej, jeśli po prostu odejdziesz, $N.$B$BAle może to właśnie ty – może to ty zniszczysz Zwój Wektorowy i powalisz Sironas. No więc? To ty?', 'Idź za Saperem Legoso i chroń go, gdy będzie próbował zniszczyć Zwój Wektorowy, a także zabij Sironas. Jeśli wykonasz misję, wróć do Egzarchy Admetiusa w Krwawej Strażnicy.', 'Zwój Wektorowy zniszczony, Sironas nie żyje', 'Wróć do Egzarchy Admetiusa na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9760, 'plPL', 'Spoczynek Obrońcy', 'Nie prosiłbym, byś w pojedynkę $gdźwigał:dźwigała; ciężar zniszczenia Zwoju Wektorowego i zabicia Sironas, $N, ale wierzę, że możesz pomóc utorować drogę innym, którzy podejmą się tak niebezpiecznego zadania.$B$BIdź drogą na północ od Krwawej Strażnicy aż do rozwidlenia. Tam skręć w lewo i idź, aż zobaczysz Spoczynek Obrońcy – będzie nieco na zachód od samej drogi. Corin będzie tam na ciebie czekać.', 'Porozmawiaj z Obrończynią Corin przy Spoczynku Obrońcy na Wyspie Krwawej Mgły.$B', '', '', '', '', '', '', 0),
(9761, 'plPL', 'Torowanie drogi', 'Tylko najbardziej zaprawieni w boju, najszlachetniejsi i zupełnie nieustraszeni draenei zgłoszą się na misję Legoso. Egzarcha nie rozkaże żadnemu agentowi Ręki, by podjął się zniszczenia Zwoju Wektorowego i uśmiercenia Sironas. Nie chce posyłać żadnego draenei na śmierć – a tym właśnie jest ta misja: samobójstwem...$B$B<Corin wzdycha.>$B$BMoim zadaniem jest osłabienie obrony Słonecznych Jastrzębi. Zabijaj Słoneczne Jastrzębie w pobliżu Zwoju Wektorowego i utrzymuj drogę wolną dla naszego czempiona – kimkolwiek się okaże.', 'Obrończyni Corin przy Spoczynku Obrońcy chce, żebyś $gzabił:zabiła; 8 sabotażystów Słonecznych Jastrzębi i 8 agentów Słonecznych Jastrzębi.$B', '', 'Wróć do Obrończyni Corin przy Spoczynku Obrońcy na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(9779, 'plPL', 'Przechwycenie wiadomości', 'Dobrze cię znów widzieć, $N. Mam pewien kłopot, który może zdołasz rozwiązać.$B$BNasi agenci za liniami Słonecznych Jastrzębi donoszą, że widzieli, jak żołnierze Słonecznych Jastrzębi odczytują jakiś nietypowy dokument.$B$BNiestety nie udało nam się zdobyć jego kopii. Wyrusz w teren i spróbuj zdobyć ten dokument. Jestem pewien, że jeśli wywrzesz dostateczny nacisk, któryś z agentów Słonecznych Jastrzębi wyda poszukiwane przez nas informacje. Użycie siły pozostawiam twojemu uznaniu.', 'Zabijaj elfy ze Słonecznych Jastrzębi, aż znajdziesz depeszę Słonecznych Jastrzębi, a potem zanieś ją Obrońcy Borosowi w Krwawej Strażnicy.', '', 'Wróć do Obrońcy Borosa w Krwawej Strażnicy na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(10063, 'plPL', 'Liga Odkrywców – czy to coś dla gnomów?', 'Niańczenie! Wyobrażasz to sobie?$B$BWyciągnęli mnie z obiecujących wykopalisk i wysłali z wyprawą kapitana Odesyusa, żebym niańczył tego małego gnoma!$B$BW życiu nie słyszałem, żeby gnom chciał zostać poszukiwaczem, no to zapytałem.$B$BWychodzi na to, że teraz bierzemy i gnomy, a ten akurat ma bzika na punkcie murloków!$B$BNo i poszedł sobie i rozbił obóz w starej skorupie żółwia na północnym brzegu wyspy. Idź i $gsam:sama; zobacz, jak mi nie wierzysz!', 'Odnajdź Cloppera Wizbanga, który obozuje w starej skorupie żółwia na brzegu na północ od Krwawej Strażnicy.', '', '', '', '', '', '', 0),
(10064, 'plPL', 'Gadaj do Ręki', 'Ręka Argusa założyła wysuniętą bazę przy Spoczynku Obrońcy, ale krwawe elfy i zmutowane zwierzęta mają nad nią dotkliwą przewagę liczebną. Bez wsparcia ten posterunek może upaść, a wtedy nie mielibyśmy jak śledzić wydarzeń w pobliżu Zwoju Wektorowego.$B$BZamelduj się u Zwiadowczyni Jorli przy Spoczynku Obrońcy, na północnym zachodzie, i zaoferuj jej pomoc, $N.', 'Zamelduj się u Zwiadowczyni Jorli przy Spoczynku Obrońcy.', '', '', '', '', '', '', 0),
(10065, 'plPL', 'Przetarcie szlaku', 'Podczas misji rozpoznania Słonecznych Jastrzębi i ich portalu zostałam ciężko ranna. Zwiadowczyni Loryi zdołała zatamować krwawienie i próbuje wymyślić, jak ewakuować mnie do Krwawej Strażnicy.$B$BKłopot w tym, że musielibyśmy opuścić tę pozycję, a bezpieczny powrót nie jest wcale pewny.$B$BGdy tylko zejdziemy z tej uświęconej ziemi, rzucą się na nas pustoszyciele. Jeśli zdołasz pozbyć się części rozwścieczonych pustoszycieli, może uda nam się bezpiecznie wrócić.', 'Zabij 10 rozwścieczonych pustoszycieli i wróć do Zwiadowczyni Jorli przy Spoczynku Obrońcy.', '', 'Wróć do Zwiadowczyni Jorli przy Spoczynku Obrońcy na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(10066, 'plPL', 'Ach, jak splątane sieci tkają', 'Nie śmiemy opuścić posterunku ani oddalić się od Spoczynku Obrońcy. Zmutowane stworzenia najbliżej Zwoju Wektorowego zostały głęboko odmienione przez energię wyciekającą z kryształów.$B$BZmutowane oplątywacze najwyraźniej zyskały pewną świadomość. Nauczyły się tworzyć, zastawiać i ukrywać okrutne pułapki, w które może wpaść nawet najostrożniejszy wojownik.$B$BNigdy nie ruszymy na Słoneczne Jastrzębie, jeśli ciągle będziemy musieli patrzeć pod nogi. Uderz w źródło problemu, $N.', 'Zabij 8 zmutowanych oplątywaczy i zamelduj się u Obrończyni Corin przy Spoczynku Obrońcy.', '', 'Wróć do Obrończyni Corin na Wyspie Krwawej Mgły.', '', '', '', '', 0),
(10067, 'plPL', 'Skalane duchy wody', 'Większość stworzeń, których dotknęła energia kryształów, uległa skażeniu w ten sam sposób: dziwne znaki na skórze, wzmożona agresja i drobne odłamki kryształów w ciele. Jednak skalane duchy wody na północ stąd zdają się całkowicie zmieniać w kryształ.$B$BNigdy wcześniej nie widziałam, żeby coś tak reagowało na kryształy. Gdy badaliśmy Plugawą Sadzawkę, były szczególnie niebezpieczne. Musimy się ich pozbyć, zanim Słoneczne Jastrzębie wykorzystają je jako nowe źródło energii.', 'Zabij 6 skalanych duchów wody i wróć do Obrończyni Corin przy Spoczynku Obrońcy.', '', 'Wróć do Obrończyni Corin na Wyspie Krwawej Mgły.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(9503, 'plPL', 'Dziękuję ci, $N. To powinno wystarczyć do zbadania tego skażenia. Wtedy lepiej będziemy wiedzieć, jak postąpić dalej.', 0),
(9504, 'plPL', 'Woda łatwo się rozstępuje, lecz gdy zbierze się jej dość, staje się siłą nie do powstrzymania. Zmywa ziemię i ogień, a powietrze bez trudu odpycha na bok.$B$BTo my jesteśmy tą niepowstrzymaną siłą, $N, a nie ci, którzy zatruli Wyspę Krwawej Mgły!', 0),
(9508, 'plPL', 'A więc stało się! Kryzys zażegnany, a ty $gzapoczątkowałeś:zapoczątkowałaś; oczyszczanie wód Wyspy Krwawej Mgły. Z czasem woda, wespół z pozostałymi żywiołami, sama się uleczy.$B$BSzkoda, że krwawe elfy nie widzą, że skażając swoje otoczenie, same siebie wyniszczają!', 0),
(9548, 'plPL', 'Fantastycznie! Kradzież mojego sprzętu dała mi lepszy wgląd w naturę tych murloków, niż mógłbym zdobyć przez całe tygodnie obserwacji!$B$BJuż wiem, co napiszę w raporcie.$B$B„W zetknięciu z wytworami kultury technologicznie wyższej Czarnomułowi nie wykazali ani krzty ciekawości charakterystycznej dla rodzących się kultur gatunków humanoidalnych”.$B$BGenialne! Panowie w Żelaznej Kuźni będą zachwyceni! Nie wiem, jak ci dziękować, $N.', 0),
(9549, 'plPL', 'Zdumiewające, po prostu zdumiewające! Są doskonałe, $N. Już widzę je pod szkłem w muzeum w Żelaznej Kuźni. Opis do gabloty praktycznie sam układa mi się w głowie!$B$BTwoja pomoc okazała się bezcenna, dzięki tobie moje badania wróciły na właściwe tory. Jak się pisze twoje imię? Dopilnuję, żeby w raporcie figurowało jako współautor.$B$BJeden z chłopaków ze statku dał mi tę „mapę skarbu” na pokrycie długu karcianego, ale mitologia to nie moja dziedzina. Przesądny ludek, ci marynarze.', 0),
(9550, 'plPL', 'Po uważnym obejrzeniu księgi dochodzisz do wniosku, że to musi być dziennik. Jego strony wypełnia eleganckie pismo, zupełnie inne niż to na mapie. Tekst wielu stron zasłaniają rysunki i zapiski ręką twórcy mapy.$B$BSpod jego opowieści o pijackich hulankach na przepustce na lądzie niemal nie sposób odczytać pierwotnego tekstu.', 0),
(9557, 'plPL', 'Hmm... to niezwykle intrygujące. Tak, powinienem zdołać odczytać, co pierwotny autor zapisał na stronach tej księgi.$B$BChyba mam wszystko, czego potrzeba. To zajmie tylko chwilę.', 0),
(9561, 'plPL', 'Trawa i krzewy porastają nienaturalny garb w ziemi.$B$BPo kilku minutach kopania odsłaniasz starą szkatułkę – niemal na pewno tę, o której wspominał dziennik Nolkaia.', 0),
(9567, 'plPL', 'Dobra robota, $N. Zobaczę, czego mogę się dowiedzieć z tego glifu, żebyśmy mogli zaplanować następny ruch.', 0),
(9569, 'plPL', 'Bez przywódcy, a do tego gdy odzyskujemy już skażone kryształy, możemy bezpiecznie trzymać satyry w ryzach. Światłość jedna wie, ile jeszcze tych nędznych stworzeń się tu czai.$B$BZwiastun Mikolaas i ja jesteśmy wdzięczni za twoją pomoc w rozprawieniu się z satyrami, zanim stały się większym zagrożeniem. Twoje dokonania przypominają, że czujność jest kluczem do zwycięstwa nad Legionem i jego sługami.', 0),
(9574, 'plPL', 'Tego aż nadto starczy do moich badań. Dziękuję ci, $N. Jeśli znajdziesz inne dowody na to, że kryształy wypaczają rodzime stworzenia Krwawej Mgły, od razu mi powiedz.', 0),
(9576, 'plPL', 'To niezwykle ciekawe, $N. Chyba nigdy wcześniej nie widzieliśmy, żeby murloki nosiły jakiekolwiek ozdoby.$B$BSkoro wiadomo, jak wypaczający wpływ mają odłamki kryształów, murlok, który nosił ten wisior, musiał wierzyć, że daje mu on władzę nad pobratymcami. Nie zdziwiłabym się, gdyby szybko przerósł innych murloków i nabrał siły.', 0),
(9578, 'plPL', 'Zwłoki są ubrane jak technik z Exodaru, ale nie ma przy nich wisiora, który opisała Morae.', 0),
(9579, 'plPL', '<Opowiadasz Morae, co $gznalazłeś:znalazłaś; we wraku Kriordzenia.>$B$BWięc... on...$B$BChyba gdzieś w głębi wiedziałam, tylko nie pozwalałam sobie w to uwierzyć. To nie te wieści, na które liczyłam, ale z całego serca dziękuję ci za odnalezienie Galaena.', 0),
(9580, 'plPL', 'Na długo zapewni nam to zapasy, a przyrządzanie tego mięsa na pewno da mi zajęcie. Dziękuję za pomoc, $N.', 0),
(9581, 'plPL', 'Ten odłamek kryształu posłuży naszym badaczom za punkt odniesienia do porównań z próbkami z innych części wyspy, bo pochodzi z jednego z mniej skażonych rejonów Krwawej Mgły.$B$BNie wyślę go, dopóki nie skompletujemy wszystkich próbek, ale to świetny początek. Jeśli zechcesz pomóc w zebraniu pozostałych, dopilnuję, żeby twój trud został nagrodzony.', 0),
(9584, 'plPL', '<Zwiastun Mikolaas bada odłamek kryształu.>$B$BTen odłamek bardzo różni się od pierwszej próbki.$B$B<Zwiastun Mikolaas unosi kryształ pod światło.>$B$BWidzisz, jak pulsuje? To niepokojące. Odnotuję w raporcie zmiany, które krwawe elfy najwyraźniej wprowadziły w tym krysztale. Jeszcze raz dziękuję za pomoc, $N.', 0),
(9585, 'plPL', '<Zwiastun Mikolaas przyjmuje od ciebie ostatni kryształ.>$B$BTo zamyka zestaw. Zostało tylko je zapakować i wysłać do Exodaru.$B$B<Zwiastun wydaje się zadowolony, że ma to zadanie za sobą.>$B$BNie zrozum mnie źle, $N, na pewno te badania są cenne, ale mamy tu na głowie wiele innych palących problemów.', 0),
(9594, 'plPL', 'Dobrze, że mi to $gprzyniosłeś:przyniosłaś;, $N. To bez wątpienia fragment pancerza strażnika Spaczenia.$B$BA więc jest tak, jak się obawiałam. Satyry Nazzivusa odnawiają kontakty z Płonącym Legionem. Jeśli ich nie powstrzymamy, satyry i ich demoniczni sojusznicy nas zaleją. Natychmiast powiadomię Zwiastuna Mikolaasa.', 0),
(9603, 'plPL', 'Więc musisz się dostać do Exodaru?$B$BTo daleka droga, ale nie martw się, mam sposób, żeby bardzo szybko cię tam dostarczyć.', 0),
(9620, 'plPL', 'Ciała draenejskich mierniczych leżą rozrzucone po ziemi, przebite bronią nag. Wszędzie walają się resztki ich zapasów i sprzętu pomiarowego, ale nigdzie nie widać ich kryształów z danymi.', 0),
(9624, 'plPL', 'Trudno było znaleźć ich wystarczająco dużo? Mnie z każdą wyprawą zajmuje to coraz więcej czasu.$B$BNiedługo będę musiał całkiem z tym skończyć, bo nie znajdę już na to czasu. Dziękuję, że $gzebrałeś:zebrałaś; dla mnie gruszki, $N. Dzięki temu upiekę jeszcze placek czy dwa, zanim skończy się sezon.', 0),
(9628, 'plPL', '<Opowiadasz Zwiastunowi Mikolaasowi o losie zespołu mierniczych. Przyjmuje od ciebie kryształ, ale długo milczy.>$B$BTo byli dobrzy ludzie, $N, i wiedzieli, że ich misja będzie niebezpieczna. Jestem wdzięczny za pomoc w odnalezieniu zespołu i odzyskaniu kryształu.$B$B<Zwiastun zaciska pięści.>$B$BStraciliśmy już zbyt wielu dobrych ludzi, a nasza misja dopiero się zaczęła.', 0),
(9629, 'plPL', 'Dobra robota, $N. Martwiłam się, że urządzenie do znakowania może zawieść, ale wygląda na to, że wszystko poszło zgodnie z planem.', 0),
(9634, 'plPL', 'Dobra robota, $N. Populację pustoszycieli trzeba będzie jeszcze długo obserwować, ale dobrze zaczęliśmy.', 0),
(9641, 'plPL', 'Dobra robota. Z tego będzie surowiec na kolejną partię kryształów wzmacniających.$B$BMożesz wybrać spośród trzech rodzajów kryształów, które potrafię wykonać. Każdy z nich przydaje mi się przy tropieniu innego rodzaju zwierzyny.', 0),
(9642, 'plPL', 'Dobrze, oto kryształy, które mam, $N. Zrób z nich dobry użytek.', 0),
(9643, 'plPL', 'Wyglądają na wystarczająco mocne. Dziękuję za pomoc, $N. Twój wkład w obronę Krwawej Strażnicy nie zostanie zapomniany.', 0),
(9646, 'plPL', 'Dobra robota. Z tego, co słyszałem, to nie mogła być łatwa walka. W pełni $gzasłużyłeś:zasłużyłaś; na nagrodę, $N.', 0),
(9647, 'plPL', 'Z czasem będziemy musieli obmyślić plan przywrócenia temu gatunkowi pierwotnego stanu, ale na razie okresowe przerzedzanie ich liczebności to chyba wszystko, na co możemy liczyć. Dziękuję za pomoc, $N.', 0),
(9648, 'plPL', 'Cóż, ostrzegałem cię, prawda? Mam nadzieję, że ta zapłata z nawiązką wynagrodzi ci drobne niedogodności, których być może $gdoznałeś:doznałaś;. Wróć do mnie, gdy nabierzesz sił, a może będę mieć dla ciebie kolejne zlecenie – oczywiście grzybowe!', 0),
(9649, 'plPL', 'Mam nadzieję, że to zadanie nie było zbyt wyczerpujące, $N. Po raz kolejny $gdowiodłeś:dowiodłaś;, że jesteś $gkompetentnym i taktownym przedstawicielem:kompetentną i taktowną przedstawicielką; swojej rasy. Przyjmij moją wdzięczność i skromną zapłatę.\n', 0),
(9663, 'plPL', 'Dobra robota, $N. To była trudna próba twoich umiejętności, ale $gprzeszedłeś:przeszłaś; ją śpiewająco. Aby zostać żołnierzem Ręki Argusa, trzeba przejść wiele takich prób.', 0),
(9666, 'plPL', 'Przykro mi, że $gmusiałeś:musiałaś; to zrobić, $N. Brutalna przemoc nie leży w naturze draenei, ale czasem nie ma innej drogi.$B$BTo jedna z tych życiowych prawd, których wielu nie rozumie, dopóki nie jest za późno. Tak było z naszym ludem, gdy orkowie wyrżnęli nas w pień.$B$BStać się Ręką Argusa to narodzić się na nowo. A narodzinom towarzyszy ból...', 0),
(9667, 'plPL', 'Po raz kolejny $gdowiodłeś:dowiodłaś;, że jesteś wszystkim, co zapowiadało proroctwo. Najwyższy wódz jest ci dozgonnie wdzięczny, $N – a do wyboru masz te relikwie Cichej Sosny...', 0),
(9668, 'plPL', 'Przeczuwałem, że zajdziesz tak daleko, $N. Jeśli chcesz iść dalej, jestem gotów cię uczyć...', 0),
(9669, 'plPL', 'Niewiarygodne! $GZnalazłeś:Znalazłaś; kogoś żywego?$B$B<Achelus zniża głos do szeptu.>$B$BPowiem szczerze, $N: nikt inny nie chciał się podjąć tej misji. Odważna z ciebie dusza...', 0),
(9670, 'plPL', '$GUratowałeś:Uratowałaś; ponad połowę zespołu! Wieść o twoim czynie na pewno dotrze do Krwawej Strażnicy i do egzarchy. Jeszcze raz dziękuję, $N.', 0),
(9671, 'plPL', 'Ty jesteś $N? Najwyższy czas! Już prawie straciłem nadzieję, że cię znajdę!$B$BW skrzynce pocztowej czeka na ciebie pilna wiadomość. Dał mi ją ludzki admirał z Lazurowej Mgły. Admirał Odesy-jakiśtam... nazwisko wyleciało mi z głowy. Powiedział, że będziesz wiedzieć, o kogo chodzi.$B$B<Hermesius wzrusza ramionami.>', 0),
(9674, 'plPL', 'Dobry początek, ale zostało jeszcze wiele do zrobienia!', 0),
(9682, 'plPL', '$GOddałeś:Oddałaś; pozbawionym nadziei wielką przysługę, $N. Zostało już tylko jedno zadanie: zgładź przywódcę przeklętych krwią.', 0),
(9683, 'plPL', 'Udało ci się! Setki dusz są ci wdzięczne za wszystko, co $gzrobiłeś:zrobiłaś;.$B$BPozwól, że złożę ci dar...', 0),
(9687, 'plPL', 'Rytuał? Lunozwierze żyły w zgodzie z tą ziemią przez tysiące lat. Coś takiego to wynaturzenie!$B$BJaka szkoda...', 0),
(9688, 'plPL', 'Jakkolwiek odrażające było twoje zadanie, trzeba było je wykonać. Teraz musisz spojrzeć złu w oczy.', 0),
(9689, 'plPL', 'Ile to już trwało? Tysiąc lat? A może dziesięć tysięcy? $GOddałeś:Oddałaś; mnie i pamięci mojego ludu wielką przysługę, $N. Przyjmij, proszę, ten przedmiot mocy w dowód wdzięczności Loreth\'Aran – na cześć twoich czynów.', 0),
(9693, 'plPL', 'Ach, $N... Słyszałem o tobie. To ty $gprzebyłeś:przebyłaś; Rajd Kessela w niecałe 15 minut, prawda? Eee, pewnie nie.$B$BJesteś $ggotów:gotowa; przelać trochę krwi w imię Światłości? Za Velena? Za Argusa?$B$B<Boros się śmieje.>$B$BDobrze, już zwalniam.', 0),
(9694, 'plPL', '$GWróciłeś:Wróciłaś; – i to w jednym kawałku!$B$BMam dobre wieści, $N. Dostaliśmy nowe informacje o tym, gdzie mogą przebywać kolejni ocaleni. Odkryto nowe miejsce katastrofy! Gdy uporam się z tymi sprawami, wezwę cię.', 0),
(9696, 'plPL', '<Elysia czyta dokument.>$B$BJeśli to, co tu napisano, jest prawdą, krwawe elfy otworzyły portal do Rubieży! To by wyjaśniało, czemu wydaje się, że nigdy ich nie ubywa...', 0),
(9700, 'plPL', 'Ile ich, mówisz, $gwidziałeś:widziałaś; przy Tłoku Osnowy? Ile razy już otwierali ten słoneczny portal? To bardzo złe wieści...$B$BCóż, nauczyłem cię już wszystkiego, czego mogłem, $N. Kuros wezwie cię, gdy nadejdzie czas.', 0),
(9703, 'plPL', 'Tylko krwawe elfy? Żadnych ocalałych? To niepokojące. Muszę to przemyśleć, $N. Może Aesom albo Boros mają dla ciebie jakieś zadanie.', 0),
(9706, 'plPL', '<Kuros blednie, czytając dziennik; łzy spływają mu po twarzy.>$B$BSaruan był moim mistrzem... moim nauczycielem... moim przewodnikiem... Zająłem jego miejsce w Triumwiracie dopiero niedawno – gdy już zaprzestaliśmy poszukiwań.$B$B<Twarz Kurosa wykrzywia gniew.>$B$BMatis...', 0),
(9711, 'plPL', 'Triumwirat postanowił natychmiast osądzić Matisa. $GPostawiłeś:Postawiłaś; dziś przed sądem arcyzbrodniarza.$B$BZnakomicie $gspisałeś:spisałaś; się przed dwoma z nas trzech; został już tylko Aesom.\n', 0),
(9740, 'plPL', 'Wyśmienicie! Odcięliśmy im linię zaopatrzenia. Teraz wystarczy ich tylko dobić!', 0),
(9741, 'plPL', 'Niezły tam bałagan, co? Dobrze się $gspisałeś:spisałaś;, $N. Wyślę kilku anachoretów na pomoc Loryi i Jorli.\n', 0),
(9746, 'plPL', 'To z pewnością osłabi ich obronę i sprawi, że dwa razy się zastanowią, zanim bezmyślnie rzucą się na nasze szeregi!', 0),
(9748, 'plPL', 'Tak jak podejrzewałem, woda zabarwiła się na czerwono od płynu wyciekającego z rdzenia.$B$BMam nadzieję, że nie $gpływałeś:pływałaś; w tej skażonej wodzie.\n', 0),
(9753, 'plPL', 'Potrzebuję twoich usług, $N. Mam plan, jak obalić całą armię Słonecznych Jastrzębi, ale zanim przejdziemy dalej, musimy zdobyć kluczowe informacje.$B$BMusimy poznać słabe punkty ich głównej linii obrony. Niestety nie zdołaliśmy podejść do Zwoju Wektorowego na tyle blisko, by ocenić ich siły. Gdybyśmy zmusili więźnia do mówienia, zdobylibyśmy informacje potrzebne do przełamania linii i zniszczenia Zwoju Wektorowego.$B$BDobrze słyszysz – chcę wysadzić to przeklęte ustrojstwo w powietrze.', 0),
(9756, 'plPL', 'Aha! Dobra robota, $N. Doprawdy dobra robota. Jesteś $ggotów:gotowa; raz na zawsze wyplenić z naszej wyspy zagrożenie ze strony krwawych elfów?', 0),
(9759, 'plPL', '$GOcaliłeś:Ocaliłaś; całą Krwawą Mgłę i Lazurową Mgłę i $gzapewniłeś:zapewniłaś; naszemu ludowi przyszłość w Azeroth, $N! Za to żadne podziękowania, żadna nagroda, nic nie będzie dość wielkie, by naprawdę wyrazić naszą wdzięczność.$B$BLecz tak wielu zostało na Draenorze i nie może być świadkami tej historycznej chwili. Musisz odnaleźć drogę powrotną. Odnajdź drogę powrotną do Rubieży, $gBohaterze:Bohaterko; Argusa. Sprowadź nasz lud do domu. Do domu, na ziemię, którą $gocaliłeś:ocaliłaś;. Do domu, do Azeroth...', 0),
(9760, 'plPL', 'Może to właśnie ty wprowadzisz nasz lud w nową erę dobrobytu i pokoju.', 0),
(9761, 'plPL', 'Oby bohater zjawił się, zanim zdołają wezwać posiłki do pilnowania terenu, który właśnie $goczyściłeś:oczyściłaś;.', 0),
(9779, 'plPL', '<Obrońca Boros przygląda się dokumentowi.>$B$BTo po thalasyjsku. Na szczęście wiem, kto może to przetłumaczyć...', 0),
(10063, 'plPL', 'Tak myślałem! Ten zrzędliwy stary krasnolud miał mi pomagać nosić sprzęt i zbierać dane, a tylko siedzi w tym dziwnym draenejskim miasteczku i upija się do nieprzytomności.', 0),
(10064, 'plPL', 'Miałam nadzieję, że Krwawa Strażnica przyśle posiłki, gdy się dowie, z czym tu mamy do czynienia.', 0),
(10065, 'plPL', 'Wygląda to trochę lepiej, ale wciąż się zastanawiam, czy nie lepiej byłoby poczekać tu na medyka.', 0),
(10066, 'plPL', 'Dobra robota, $N. Teraz dużo łatwiej będzie ściągać posiłki z Krwawej Strażnicy albo uderzać na Słoneczne Jastrzębie bez obaw o to, co knują oplątywacze.', 0),
(10067, 'plPL', 'Dobra robota, $N. Nie wolno przegapić żadnej okazji, by odciąć Słoneczne Jastrzębie od zasobów.', 0),
(11738, 'plPL', 'Zbezcześć wielkie ognisko Przymierza na Wyspie Krwawej Mgły!', 0),
(11809, 'plPL', 'Uczcij płomień Wyspy Krwawej Mgły!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(4982, 'plPL', 'Udało się?', 0),
(5001, 'plPL', 'Udało się?', 0),
(5102, 'plPL', 'Zrobione?', 0),
(9503, 'plPL', 'Czyżbyś już $gzebrał:zebrała; plugawe esencje moich nieszczęsnych sióstr, $N?', 0),
(9504, 'plPL', 'Masz czystą wodę z ruin?', 0),
(9508, 'plPL', 'Udało ci się?', 0),
(9548, 'plPL', 'Udało ci się znaleźć mój sprzęt?', 0),
(9549, 'plPL', 'Masz te okazy, które mam wysłać do Żelaznej Kuźni?', 0),
(9550, 'plPL', 'Może to właśnie ten stary dziennik wskazuje mapa.', 0),
(9557, 'plPL', 'Niech Światłość oświetla wszystkie twoje poczynania, $N. Co tam masz?', 0),
(9567, 'plPL', 'Czy udało ci się dowiedzieć czegoś o satyrach Nazzivusa?', 0),
(9569, 'plPL', '<Obrończyni Aalesia zdaje się patrzeć przez ciebie, a nie na ciebie – myślami jest przy rozprawie z satyrami.>$B$BCzy $gwyruszyłeś:wyruszyłaś; już przeciw przywódcy satyrów, jak prosiłam?', 0),
(9574, 'plPL', 'Udało ci się zdobyć potrzebne mi próbki?', 0),
(9576, 'plPL', 'Co tam masz?', 0),
(9579, 'plPL', '<Morae patrzy na ciebie z nadzieją.>$B$BCzy $gnatrafiłeś:natrafiłaś; na jakiś ślad Galaena?', 0),
(9580, 'plPL', 'Jak idą łowy, $N?', 0),
(9581, 'plPL', 'Udało ci się zdobyć pierwszą próbkę kryształu?', 0),
(9584, 'plPL', 'Masz drugą próbkę kryształu?', 0),
(9585, 'plPL', '$GWróciłeś:Wróciłaś; z ostatnią próbką do mojego zestawu?', 0),
(9594, 'plPL', 'Tak, $N? Co tam masz?', 0),
(9603, 'plPL', 'Dzień dobry, $N. Chcesz wynająć hipogryfa?', 0),
(9624, 'plPL', 'Piaskowe gruszki coraz trudniej znaleźć, a to oczywiście oznacza mniej placków i mniej przysmaków dla tutejszych elekków. Udało ci się zebrać wszystkie owoce, których potrzebuję?', 0),
(9628, 'plPL', 'Udało ci się ustalić, co zatrzymało zespół mierniczych?', 0),
(9629, 'plPL', 'Urządzenie zadziałało? $GOznakowałeś:Oznakowałaś; murloki do moich badań?', 0),
(9634, 'plPL', 'Musimy działać, zanim pustoszyciele wyprą rodzime drapieżniki Wyspy Krwawej Mgły. $GZacząłeś:Zaczęłaś; już przetrzebiać populację pustoszycieli?', 0),
(9641, 'plPL', '$GZebrałeś:Zebrałaś; odłamki kryształów ze stworzeń Krwawej Mgły?', 0),
(9642, 'plPL', 'Jeśli masz więcej napromieniowanych odłamków kryształu, chętnie wymienię je na kolejny z moich kryształów.', 0),
(9643, 'plPL', 'Udało ci się zdobyć pnącza dusicieli?', 0),
(9646, 'plPL', 'W czym mogę ci pomóc, $N?', 0),
(9647, 'plPL', '$GPrzetrzebiłeś:Przetrzebiłaś; ćmy?', 0),
(9648, 'plPL', 'Pamiętaj, każdy z grzybów, o które proszę, rośnie tylko w innym zakątku Krwawej Mgły.', 0),
(9649, 'plPL', 'Już wracasz?', 0),
(9663, 'plPL', 'Nie czas na odpoczynek!', 0),
(9666, 'plPL', 'Zrobione?', 0),
(9667, 'plPL', 'Nie zostało mi wiele czasu, $N. Niedługo mnie zabiją...', 0),
(9669, 'plPL', 'To była straszna jatka...', 0),
(9670, 'plPL', 'Udało się?', 0),
(9674, 'plPL', 'To paskudne stwory...', 0),
(9682, 'plPL', 'Nie opłakuj ich, $N.', 0),
(9683, 'plPL', 'Trzeba wywabić Atopha!', 0),
(9687, 'plPL', 'Smocze wojny dawno minęły. Zostały tylko kości i niespokojne szczątki stada Ysery.', 0),
(9688, 'plPL', 'Boli mnie ten widok. Proszę, nie mówmy już o tym.', 0),
(9689, 'plPL', 'Radzę ci zabrać sojuszników, $N.', 0),
(9694, 'plPL', 'Jest ich tak wielu, że nie mogę oprzeć się wrażeniu, że jakimś sposobem się mnożą.', 0),
(9696, 'plPL', 'Jestem trochę zajęta, $gagencie:agentko; $N. Oby to było coś ważnego.', 0),
(9700, 'plPL', 'Dochodzą mnie meldunki o dziwnych stworzeniach, które pojawiają się w okolicy. Czy to zmutowane miejscowe zwierzęta, czy prawdziwe anomalie Pustki – tego musisz się dowiedzieć.', 0),
(9703, 'plPL', 'Czy te informacje się potwierdziły?', 0),
(9706, 'plPL', 'Co tam masz, $N? Czy to dziennik?', 0),
(9740, 'plPL', 'Zanim zniszczysz samą bramę, musisz zlikwidować kontrolery portalu!', 0),
(9741, 'plPL', 'Zwierzaki Pustki wyrastają na anomalie Pustki. Prawdę mówiąc, nie wiemy, czym właściwie są te stworzenia... ta nazwa to raczej klasyfikacja.', 0),
(9746, 'plPL', 'Ich przywódczyni nie będzie się przed nami ukrywać wiecznie. Będziemy metodycznie sprawdzać każdą możliwą kryjówkę, aż znajdziemy Sironas.', 0),
(9748, 'plPL', 'Nie pij tej wody, $N!', 0),
(9761, 'plPL', 'Widzisz tu gdzieś wyjątkowo odważnych i potężnych draenei?', 0),
(9779, 'plPL', 'Już $gwróciłeś:wróciłaś;? $GZnalazłeś:Znalazłaś; depeszę?', 0),
(9999, 'plPL', 'Już wracasz?', 0),
(10011, 'plPL', 'Zrobione?', 0),
(10065, 'plPL', 'Udało ci się pozbyć części pustoszycieli z okolicy?', 0),
(10066, 'plPL', 'Udało ci się pozbyć choć części zmutowanych oplątywaczy?', 0),
(10067, 'plPL', '$GZacząłeś:Zaczęłaś; już oczyszczać okolicę ze skalanych duchów wody?', 0),
(10522, 'plPL', 'Udało się?', 0),
(10588, 'plPL', 'Zrobione?', 0),
