(22647, 'plPL', 'Przepis: chrupka pajęcza niespodzianka', 'Uczy przyrządzania chrupkiej pajęczej niespodzianki.', 0),
(23744, 'plPL', 'Plugawa esencja', 'Zapach tej wodnistej pozostałości jest naprawdę odrażający.', 0),
(23749, 'plPL', 'Pusty bukłak', '', 0),
(23750, 'plPL', 'Napełniony bukłak', 'Czystość wody w środku sprawia, że bukłak lekko świeci.', 0),
(23751, 'plPL', 'Bukłak najczystszej wody', '', 0),
(23830, 'plPL', 'Sprzęt Cloppera', 'Sprzęt wydaje się nieuszkodzony, choć trochę oślizgły.', 0),
(23833, 'plPL', 'Prymitywny nóż murloków', 'Prymitywnie ociosane kamienne ostrze przywiązane ścięgnem do długiego kija.', 0),
(23834, 'plPL', 'Prymitywny idol murloków', 'Z grubsza wyrzeźbiony idol, który nie przedstawia żadnej rozpoznawalnej postaci.', 0),
(23837, 'plPL', 'Zniszczona mapa skarbów', 'Pergamin jest pożółkły, wyblakły i dziurawy, ale większość pisma wciąż da się odczytać.', 0),
(23844, 'plPL', 'Latarnia Nolkaia', '', 0),
(23846, 'plPL', 'Szkatułka Nolkaia', '', 0),
(23847, 'plPL', 'Obrączka Nolkaia', 'Napis po wewnętrznej stronie obrączki głosi: Upominek, by mój ukochany o mnie pamiętał. Niech Elune czuwa nad moim drogim Nolkaiem.', 0),
(23851, 'plPL', 'Sfatygowany dziennik', 'Okładka dziennika jest mocno wytarta, a kartki pożółkłe, ale wciąż widać w nim zapiski dwóch rąk.', 0),
(23852, 'plPL', 'Torba Nolkaia', 'Choć długo leżała zakopana w ziemi, ta torba wygląda niemal jak nowa.', 0),
(23859, 'plPL', 'Glif z Pomnika Nazzivusa', 'Złowrogo wyglądające znaki towarzyszą szeregowi humanoidalnych postaci, tworząc jakąś opowieść.', 0),
(23863, 'plPL', 'Skażony kryształ', 'Kryształ pulsuje gniewnym czerwonym światłem. Trudno uwierzyć, że kiedyś był częścią Exodaru.', 0),
(23869, 'plPL', 'Skrystalizowana kora', 'W korę wrosły kawałki czerwonego kryształu i zdają się wypierać drewno.', 0),
(23870, 'plPL', 'Wisior z czerwonym kryształem', 'Ozdoba zrobiona z odłamka kryształu i skręconego sznurka z wodorostów.', 0),
(23873, 'plPL', 'Amulet Galaena', 'Na końcu cienkiego łańcuszka zwisa mały talizman wysadzany klejnotami.', 0),
(23875, 'plPL', 'Kryształowy kilof górniczy', '', 0),
(23876, 'plPL', 'Kryształowy kilof górniczy', '', 0),
(23877, 'plPL', 'Kryształowy kilof górniczy', '', 0),
(23878, 'plPL', 'Próbka kryształu z miejsca uderzenia', 'Bryłka kryształu ze szczątków rozbitego Exodaru.', 0),
(23879, 'plPL', 'Próbka zmienionego kryształu', 'Odłamek kryształu, który był kiedyś częścią Exodaru, ale został przerobiony przez krwawe elfy.', 0),
(23880, 'plPL', 'Próbka kryształu z Axxarien', 'Próbka odłupana z kryształów znalezionych w osadach satyrów.', 0),
(23900, 'plPL', 'Płyta pancerza Tzeraka', 'Kawałek opancerzenia wycięty z ciała strażnika Spaczenia Tzeraka.', 0),
(23927, 'plPL', 'Piaskowa gruszka', 'Jaskrawy, soczysty owoc, przysmak elekków.', 0),
