INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(2925, 'plPL', 'Naprawa statków transwymiarowych dla prostaczków, Jamus Kaesi$B$B<Cienkie stronice tej księgi wykonano z mieniącego się materiału. Wypełniają je wysoce techniczne schematy, które pokazują, jak konserwować i naprawiać statek transwymiarowy. Ten egzemplarz jest otwarty na rozdziale zatytułowanym „Wyłomy w zwojach wektorowych i jak ich unikać”.>', 0),
(2937, 'plPL', 'Patrzyłem, jak biją go bez litości. Ich bezwzględny porucznik zachowywał się, jakby takie okrucieństwo było czymś zwyczajnym. Przy każdym brutalnym ciosie czułem, że coś we mnie pęka.$B$BPatrząc, jak Obrońca Saruan przyjmuje ich razy, zacząłem płakać. Nie ze strachu... płakałem ze smutku. Widzieć, jak draenei z Triumwiratu jest tak traktowany. Gdybym tylko mógł zerwać więzy. Gdybym tylko...$B', 0),
(2938, 'plPL', 'Po czymś, co zdawało się wiecznością, Obrońca stracił przytomność. Tortury okazały się zbyt ciężkie nawet dla niego. Ten okrutnik – Matis, jak się dowiedziałem – próbował ocucić Saruana, chlustając na jego zmasakrowane ciało wodą zatrutą zarazą. Ale Saruan się nie ocknął.$B', 0),
(2939, 'plPL', 'Chciałem krzyczeć, ale z moich ust wydobył się tylko cichy jęk. Natychmiast mnie za ten akt buntu pobito. Leżąc na ziemi, widziałem, jak Matis krąży przed ciałem Saruana. Był wyraźnie zaniepokojony. Oznajmił, że Sironas czy Sirona, czy jakaś inna istota obedrze go ze skóry, jeśli Saruan zmarł od tego bicia.', 0),
(2940, 'plPL', 'Że ta istota, Sironas, miała wobec Saruana plany...$B$B<Pismo urywa się nagle, a przez stronę biegnie długa kreska. Ten draenei umarł, pisząc te słowa.>$B', 0);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(12177, 'plPL', 'Na tej tablicy wiszą różne ogłoszenia i obwieszczenia o nagrodach.', '', 0),
(14030, 'plPL', '', 'Te piktogramy opowiadają historię. Ta postać na początku wygląda niemal jak jedno ze stworzeń, które spotkaliśmy przy Lazurowej Strażnicy...', 0),
(14031, 'plPL', '', 'Nie, to niemożliwe... Tu jest napisane, że ta istota z własnej woli została sługą Legionu. Zmienia się w satyra i otrzymuje „błogosławieństwo” Legionu.', 0),
(14032, 'plPL', '', 'Musimy pokonać te satyry, $n. Nie pozwolimy, by Legion panoszył się na tych ziemiach.', 0),
(14070, 'plPL', 'Głupcy! Słabeusze! Tzerak nie potrzebuje waszej pomocy!', '', 0),
(14260, 'plPL', 'Jestem Admetius, dowódca Krwawej Strażnicy.', '', 0),
(14268, 'plPL', 'Na Argusie Mac\'Aree było najświętszym z naszych miast.$B$BUwierzysz, jeśli powiem, że chodniki wykładano tam szlachetnymi minerałami? Że rzeki lśniły nawet w zupełnej ciemności?$B$BTęsknię za tamtymi dniami... Ile to już minęło? Tysiąc lat? Dziesięć tysięcy?', '', 0),
(14269, 'plPL', 'Gdybym tylko mógł wrócić do grzybowego gąszczu. Nigdy w życiu nie widziałem tak dojrzałej kępy!', '', 0),
(14301, 'plPL', 'Jeśli podczas pobytu na Krwawej Mgle masz się nauczyć tylko jednego, $N, to mam nadzieję, że czujności. Ta wyspa najpierw pochłania nieostrożnych, a potem powoli kruszy nawet najczujniejszych wojowników.$B$BGdziekolwiek się obrócisz, czeka wróg gotów odebrać ci życie.', '', 0),
(14302, 'plPL', '', 'Wszystko, co wydarzyło się od katastrofy, zlewa mi się w jedną mglistą plamę. Mam wrażenie, że całe życie minęło, odkąd byłam na pokładzie Exodaru.$B$BTeraz mój świat to tylko ta wyspa, jej zmutowane stworzenia i niekończące się morze agentów krwawych elfów. Wkrótce będzie tak, jakbym nigdy nie znała niczego innego...', 0),
(14303, 'plPL', 'Inni patrzą na tę okolicę i widzą tylko śmierć, skażenie i przeciwności. Tego, owszem, tu nie brakuje, ale taki pogląd pomija możliwości, jakie daje nam otoczenie.$B$BNie będę się bezczynnie przyglądać, jak te możliwości przepadają, $N. Z twoją pomocą pokażemy innym w Krwawej Strażnicy, jak zrobić użytek z otoczenia i jego stworzeń.', '', 0),
(14304, 'plPL', 'Witaj, $N.$B$BStary Kessel, o tam, to spryciarz. Na twoim miejscu bardzo bym uważał w interesach z nim.$B$BZaproponował mi pracę przy „opiece nad elekkami”, a ja, głupi, zrozumiałem przez to karmienie, tresurę i tak dalej. Wszystko stało się jasne, kiedy wręczył mi łopatę...', '', 0),
(14317, 'plPL', 'Jestem Kessel, pan elekków, uczeń Ręki Argusa. Czy to ty jesteś $gnowym rekrutem:nową rekrutką;?', '', 0),
(14322, 'plPL', 'Poczuj gniew Szczecinołapów!', '', 0),
(14323, 'plPL', 'Dziękuję za ratunek, $n! Mój ojciec będzie zachwycony!', '', 0),
(14324, 'plPL', 'Jestem Achelus, główny oficer ekspedycyjny Krwawej Strażnicy.', '', 0),
(14325, 'plPL', 'Dostarczam pocztę do Lazurowej Mgły i z powrotem, $N. Jeśli chcesz coś komuś przekazać, najpewniej najpierw trafi to do mnie.', '', 0),
(14327, 'plPL', 'Przysłali cię, żebyś mnie $godnalazł:odnalazła;? Cóż, nie wrócę bez moich ludzi.', '', 0),
(14328, 'plPL', 'Czy wy nigdy nie sprawdzacie poczty?', '', 0),
(14329, 'plPL', 'Jak niby mam dostarczyć te wszystkie wiadomości?', '', 0),
(14330, 'plPL', 'Muszę dostać inny przydział. Ta robota doprowadza mnie do szału...', '', 0),
(14331, 'plPL', 'Któregoś dnia wyciągnę kryształowego zgładziciela i urządzę temu miastu prawdziwą orkową jatkę. Wtedy pożałują...', '', 0),
(14332, 'plPL', 'Myśli, że jest taki cholernie ważny. Ciągle mną pomiata... Ja mu jeszcze pokażę. Pokażę im wszystkim!', '', 0),
(14346, 'plPL', 'Jesteśmy wolni! Jesteśmy wolni!', 'Jesteśmy wolni! Jesteśmy wolni!', 0),
(14347, 'plPL', 'Hura! Dzięki!', 'Hura! Dzięki!', 0),
(14348, 'plPL', 'Na znak na czole Velena, jestem ocalony!', 'Na znak na czole Velena, jestem ocalony!', 0),
(14349, 'plPL', 'Wiedziałem, że Cornelius nas nie zostawi!', 'Wiedziałem, że Cornelius nas nie zostawi!', 0),
(14362, 'plPL', 'Ciii! Bądź bardzo cicho, obserwuję murloki.$B$BMieszkanie w przerośniętej skorupie żółwia to poświęcenie, na które jestem gotów dla nauki. W końcu jeśli murloki mnie tu zobaczą, zareagują na moją obecność i zanieczyszczą mi dane!$B$BJako pierwszy gnomi członek Ligi Odkrywców śmiało zmierzam tam, gdzie nie dotarł jeszcze żaden krasnolud!', '', 0),
(14366, 'plPL', 'Kto śmie bezcześcić posąg naszej ukochanej?', '', 0),
(14369, 'plPL', '$GOszalałeś:Oszalałaś;? Rozejrzyj się, $gśmiertelniku:śmiertelniczko;. Nie widzisz, że stoisz na rozdartej ziemi? Odejdź stąd, byś nie $gcierpiał:cierpiała; tak jak mój lud i ja...', '', 0),
(14370, 'plPL', 'Dlaczego cierpisz?', 'Dlaczego cierpisz?', 0),
(14371, 'plPL', 'Jesteś nie tylko $gszalony:szalona;, ale i $gślepy:ślepa;?$B$BJestem duchem – okrutnym przypomnieniem cywilizacji, która dawno przestała istnieć – przykutym do ziemi, której nie zdołałem obronić.$B$BDawno temu – dziesięć tysięcy lat temu – byłem z krwi i kości, tak jak ty. Byłem księciem tej krainy i smoczym jeźdźcem, pobłogosławionym przez Yserę ze Szmaragdowego Snu.', '', 0),
(14372, 'plPL', 'Kim jest Ysera i jak cię pobłogosławiła?', 'Kim jest Ysera i jak cię pobłogosławiła?', 0),
(14373, 'plPL', 'Nie $gsłyszałeś:słyszałaś; o Yserze? Strażniczce natury? Aspekcie Snu? To matrona wszystkich zielonych smoków! Tak, to sama Ysera obdarzyła moje królestwo swoim stadem. Stawaliśmy ramię w ramię z tymi szlachetnymi stworzeniami, a one pozwalały nam dosiadać się w bitwach z naszymi wrogami. Przez wiele stuleci wszystko było dobrze... aż do...', '', 0),
(14374, 'plPL', 'Aż do czego?', 'Aż do czego?', 0),
(14375, 'plPL', 'Stado Śmiercioskrzydłego... Życzliwość Ysery wzbudziła gniew Śmiercioskrzydłego – patrona Czarnego Stada. Napadli na nas we śnie! Wielu zginęło w pierwszym natarciu, ale zielone smoki powstały, by nas chronić.$B$B<Książę Toreth wskazuje wyspę wokół.>$B$BTe kości to wszystko, co zostało z niegdyś wielkich smoków. Nikogo nie oszczędzono.', '', 0),
(14376, 'plPL', 'Dlaczego więc wciąż tu jesteś?', 'Dlaczego więc wciąż tu jesteś?', 0),
(14377, 'plPL', 'Zginąłem ostatni. Czując, jak duch opuszcza moją śmiertelną powłokę, złożyłem przysięgę krwi.$B$B<Książę Toreth kręci głową.>$B$BZawarłem pakt z tą ziemią: moja krew za ten świat. Stałem się jedynym strażnikiem historii mojego ludu.$B$BNie zaznam spoczynku, dopóki nie będę pewien, że opowieść o smoczych jeźdźcach z Loreth\'Aran nie zaginie w mrokach dziejów.\n', '', 0),
(14422, 'plPL', 'Witaj, $N. Jestem Kuros, drugi z Triumwiratu Ręki.', '', 0),
(14428, 'plPL', 'Patrzyłem, jak biją go bez litości. Ich bezwzględny porucznik zachowywał się, jakby takie okrucieństwo było czymś zwyczajnym. Przy każdym brutalnym ciosie czułem, że coś we mnie pęka.$B$BPatrząc, jak Obrońca Saruan przyjmuje ich razy, zacząłem płakać. Nie ze strachu... płakałem ze smutku. Widzieć, jak draenei z Triumwiratu jest tak traktowany. Gdybym tylko mógł zerwać więzy. Gdybym tylko...\n', '', 0),
(14444, 'plPL', '%s traci przytomność.', '', 0),
(14447, 'plPL', 'Nigdy nie weźmiecie mnie żywcem!', '', 0),
(14454, 'plPL', 'Chcę, żeby wszyscy twoi tropiciele wyruszyli na poszukiwanie zbrodniarza, Matisa Okrutnego. Dałem rakietnice zaufanym agentom Ręki. Jeśli ty albo któryś z twoich tropicieli zobaczy racę, będzie to znak, że agent odnalazł Matisa i potrzebuje pomocy. I pamiętaj, tropicielu: Matis ma zostać przyprowadzony do mnie żywy.', '', 0),
(14563, 'plPL', 'Jestem Aesom, trzeci z Triumwiratu.', '', 0),
(14593, 'plPL', '', 'Niech szlag trafi te krwawe elfy i ich lekkomyślną magię!', 0),
(14622, 'plPL', 'Ciesz się, że siedzę zamknięty w tej klatce.', 'Ciesz się, że siedzę zamknięty w tej klatce.', 0),
(14625, 'plPL', '<Schwytany agent Słonecznych Jastrzębi przygląda ci się podejrzliwie.>$B$BNigdy cię wcześniej nie widziałem. Kim jesteś?', '<Schwytany agent Słonecznych Jastrzębi przygląda ci się podejrzliwie.>$B$BNigdy cię wcześniej nie widziałem. Kim jesteś?', 0),
(14626, 'plPL', 'Jestem więźniem, nie widać? To draenejskie ścierwo pojmało mnie, gdy $gwychodziłem:wychodziłam; ze Słonecznej Bramy. Zabili naszych kontrolerów portalu i zniszczyli bramę. Król Słońca będzie bardzo niezadowolony z takiego obrotu spraw.', 'Jestem więźniem, nie widać? To draenejskie ścierwo pojmało mnie, gdy $gwychodziłem:wychodziłam; ze Słonecznej Bramy. Zabili naszych kontrolerów portalu i zniszczyli bramę. Król Słońca będzie bardzo niezadowolony z takiego obrotu spraw.', 0),
(14627, 'plPL', '<Schwytany agent Słonecznych Jastrzębi uśmiecha się drwiąco.>$B$BNie martw się, żółtodziobie, mamy jeszcze wielu kontrolerów portalu i mnóstwo dobrych miejsc na portale. Jestem pewien, że Sironas wkrótce postawi nową bramę. Te niebieskoskóre psy nie pożyją już długo na tym świecie. Sironas i ta abominacja uprzątną wszystko, co zostawią po sobie siły Słonecznych Jastrzębi.', '<Schwytany agent Słonecznych Jastrzębi uśmiecha się drwiąco.>$B$BNie martw się, żółtodziobie, mamy jeszcze wielu kontrolerów portalu i mnóstwo dobrych miejsc na portale. Jestem pewien, że Sironas wkrótce postawi nową bramę. Te niebieskoskóre psy nie pożyją już długo na tym świecie. Sironas i ta abominacja uprzątną wszystko, co zostawią po sobie siły Słonecznych Jastrzębi.', 0),
(14628, 'plPL', 'Ach tak, Sironas. Prawie $gzapomniałem:zapomniałam;, że Sironas tu jest. $GSłużyłem:Służyłam; pod jej rozkazami jeszcze w Rubieży. Ale o tej abominacji nie $gsłyszałem:słyszałam; – te przeklęte draenei pojmały mnie, zanim w ogóle w pełni $gzmaterializowałem:zmaterializowałam; się na tym świecie.', 'Ach tak, Sironas. Prawie $gzapomniałem:zapomniałam;, że Sironas tu jest. $GSłużyłem:Służyłam; pod jej rozkazami jeszcze w Rubieży. Ale o tej abominacji nie $gsłyszałem:słyszałam; – te przeklęte draenei pojmały mnie, zanim w ogóle w pełni $gzmaterializowałem:zmaterializowałam; się na tym świecie.', 0),
(14629, 'plPL', 'To był pomysł Sironas... Ta abominacja to w rzeczywistości jeden z nich. Wysoko postawiony członek draenejskiego zakonu wojskowego: Triumwiratu czy innej bzdury.$B$BCzymkolwiek to jest, jest ogromne, potężne i pełne wściekłości. Każdy atak na Zwój Wektorowy na pewno się nie powiedzie, dopóki ta abominacja jest w pobliżu.', 'To był pomysł Sironas... Ta abominacja to w rzeczywistości jeden z nich. Wysoko postawiony członek draenejskiego zakonu wojskowego: Triumwiratu czy innej bzdury.$B$BCzymkolwiek to jest, jest ogromne, potężne i pełne wściekłości. Każdy atak na Zwój Wektorowy na pewno się nie powiedzie, dopóki ta abominacja jest w pobliżu.', 0),
(14630, 'plPL', 'Niesamowite. Jak Sironas tego dokonała?', 'Niesamowite. Jak Sironas tego dokonała?', 0),
(14631, 'plPL', 'Sironas twierdzi, że niektórzy eredarowie potrafią przemieniać innych ze swojej rasy w man\'ari. Draenei byli podobno kiedyś eredarami, a Sironas jest potężną eredarką.$B$B<Agent się śmieje.>$B$BWyobrażasz sobie? Te żałosne stworzenia były kiedyś wszechpotężnymi demonami. Jaki głupiec odrzuca taką moc?\n', 'Sironas twierdzi, że niektórzy eredarowie potrafią przemieniać innych ze swojej rasy w man\'ari – dzikie, demoniczne istoty. Draenei byli podobno kiedyś eredarami, a Sironas jest potężną eredarką.$B$B<Agent się śmieje.>$B$BWyobrażasz sobie? Te żałosne stworzenia były kiedyś wszechpotężnymi demonami. Jaki głupiec odrzuca taką moc?\n', 0),
(14632, 'plPL', 'Sironas jest eredarką... To znaczy, tak, oczywiście.', 'Sironas jest eredarką... To znaczy, tak, oczywiście.', 0),
(14633, 'plPL', 'Oczywiście. Jak inaczej mogłaby przeniknąć do ich szeregów i uchodzić za draenei? Żyła wśród nich od bardzo dawna.', 'Oczywiście. Jak inaczej mogłaby przeniknąć do ich szeregów i uchodzić za draenei? Żyła wśród nich od bardzo dawna.', 0),
(14634, 'plPL', 'Zwój Wektorowy jest ogromny. Mam nadzieję, że mamy więcej niż jedną abominację na straży licznych słabych punktów.', 'Zwój Wektorowy jest ogromny. Mam nadzieję, że mamy więcej niż jedną abominację na straży licznych słabych punktów.', 0),
(14635, 'plPL', 'Licznych? Ma dwa słabe punkty: podstawę konstrukcji po zachodniej stronie i podstawę konstrukcji po wschodniej stronie. Hej, zaraz. Skąd ty w ogóle wiesz cokolwiek o Zwoju Wektorowym? Nie $gmówiłeś:mówiłaś;, że cię pojmali, zanim w ogóle się $gzmaterializowałeś:zmaterializowałaś;?', 'Licznych? Ma dwa słabe punkty: podstawę konstrukcji po zachodniej stronie i podstawę konstrukcji po wschodniej stronie. Hej, zaraz. Skąd ty w ogóle wiesz cokolwiek o Zwoju Wektorowym? Nie $gmówiłeś:mówiłaś;, że cię pojmali, zanim w ogóle się $gzmaterializowałeś:zmaterializowałaś;?', 0),
(14636, 'plPL', '$GMówiłem:Mówiłam;, a ty mi uwierzyłeś. Dziękuję za informacje, krwawy elfie. Pomogłeś nam bardziej, niż możesz przypuszczać.', '$GMówiłem:Mówiłam;, a ty mi uwierzyłeś. Dziękuję za informacje, krwawy elfie. Pomogłeś nam bardziej, niż możesz przypuszczać.', 0),
(14647, 'plPL', 'Nadszedł czas, by zniszczyć Zwój Wektorowy!', '', 0),
(14648, 'plPL', 'Nie ma już odwrotu, $n. Trzymaj się blisko i osłaniaj mi plecy.', '', 0),
(14649, 'plPL', 'Tam jest! Widzisz, gdzie ten wielki czerwony kryształ wystaje ze Zwoju Wektorowego? Tam muszę podłożyć pierwsze ładunki wybuchowe.', '', 0),
(14650, 'plPL', 'Osłaniaj mnie!', '', 0),
(14651, 'plPL', 'To już nie potrwa długo, $n. Tylko trzymaj ich z dala ode mnie, kiedy pracuję.', '', 0),
(14652, 'plPL', 'Gotowe! Szybko, kryj się!', '', 0),
(14656, 'plPL', 'Nie ciesz się za bardzo, $gbohaterze:bohaterko;, to była ta łatwa część. Najtrudniejsze przed nami! Idziemy.', '', 0),
(14657, 'plPL', 'Co to, do Otchłani, jest?!?!', '', 0),
(14658, 'plPL', 'Bądź $ggotów:gotowa; na wszystko, $n.', '', 0),
(14659, 'plPL', 'Błogosławiona Światłości! Ona wysysa energię prosto ze Zwoju Wektorowego!', '', 0),
(14660, 'plPL', 'Osłaniaj mnie, musimy to zrobić szybko. Kiedy wysadzę podporę po tej stronie, strumienie energii zostaną zakłócone i ona się uwolni! Wątpię, żeby ucieszyła się na nasz widok.', '', 0),
(14661, 'plPL', 'Prawie gotowe! Jeszcze tylko chwila...', '', 0),
(14662, 'plPL', 'Kryj się i szykuj na walkę swojego życia, $n!', '', 0),
(14663, 'plPL', 'Święta matko O\'rosa!', '', 0),
(14664, 'plPL', 'Ja... nie mogę uwierzyć, że to koniec. Udało ci się! $GZniszczyłeś:Zniszczyłaś; krwawe elfy i ich przywódczynię!', '', 0),
(14665, 'plPL', 'Wracaj do Krwawej Strażnicy. Zobaczymy się tam...', '', 0),
(14666, 'plPL', '', 'Rozkapryszone dzieci, módlcie się do swoich bogów, bo zaraz ich spotkacie!', 0),
(14667, 'plPL', '', 'Cierpliwie czekam na rozkazy, $N.', 0),
(14691, 'plPL', 'Chwała $n, $gwybawcy:wybawczyni; Lazurowej i Krwawej Mgły! $GBohaterowi:Bohaterce; Ręki Argusa, $gczempionowi:czempionce; ludu draenei!', '', 0),
(14718, 'plPL', '', 'Dowodzę obroną Krwawej Strażnicy. W czym mogę pomóc?', 0),
(14720, 'plPL', '', 'Witaj. Chcesz się dowiedzieć czegoś o konflikcie na Krwawej Mgle?', 0),
(14722, 'plPL', '', 'Służymy Światłości bez zadawania pytań. Ale może ty chcesz wiedzieć nieco więcej o tym, czemu tu jesteśmy?', 0),
(14723, 'plPL', 'Opowiedz mi o defensorach.', 'Opowiedz mi o defensorach.', 0),
(14794, 'plPL', '', 'Defensorzy Krwawej Strażnicy chronią tę placówkę przed wszelkim zagrożeniem.', 0),
(14795, 'plPL', '', 'Defensorzy są tu, by chronić Krwawą Strażnicę przed zagrożeniem ze strony Słonecznych Jastrzębi.', 0),
(14796, 'plPL', '', 'Niedawno doszły nas wieści, że w pobliżu Zwoju Wektorowego przyzwano istotę o niezmierzonej mocy. Bez obaw – jeśli cokolwiek zagrozi osadzie, oddamy życie w jej obronie.', 0),
(14941, 'plPL', 'Na tej tablicy wiszą różne ogłoszenia i obwieszczenia o nagrodach.', '', 0),
(15933, 'plPL', '<Gdy pozdrawiasz ambasadora Frasaboo w języku furbolgów, ten się uśmiecha.>$B$BMusisz być $gtym:tą;, o $gktórym:której; mówi przepowiednia. To dla mnie wielki zaszczyt cię poznać.$B$BJestem ambasador Frasaboo, przedstawiciel Najwyższego wodza Cichej Sosny w Krwawej Strażnicy.', '', 0),
(15935, 'plPL', 'Przez te lata w Lidze Odkrywców zjeździłem całe Azeroth, ale czegoś takiego jak Krwawa Mgła jeszcze nie widziałem.', '', 0),
(15938, 'plPL', '', 'Dopiero co tu przybyliśmy, a już pochowaliśmy zbyt wielu przyjaciół i towarzyszy broni.', 0),
(18780, 'plPL', '', 'Witaj, jestem Azimi! Często przychodzę tu sprzedawać żołnierzom świeże owoce i wodę. Jesteś $ggłodny:głodna;, a może $gspragniony:spragniona;?', 0),
(26852, 'plPL', 'Osłaniaj mnie!', 'Osłaniaj mnie!', 0),
(29725, 'plPL', '%s traci przytomność.', '%s traci przytomność.', 0);
